insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "d50ab6a8-7d3e-4a67-bcb0-0776599cb68a", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 15, "content": "Dave Taylor (37:33): Sure. So it's something that has been rattling around in my head since I started. Ok, bro. And as you've been doing this for a long time, especially I think in the beginning of your career as you're trying to find yourself as a creative, it's a lot easier to be cynical about the other work that's not very good rather than really being a fan of the work. That's good. And that's how you're finding yourself and your place in the world, and that can end up being detrimental, spending a lot of your time in this negative place where it's even looking at really good work. You're like, oh, they only got to do that work because they're working at this place. I could do that myself instead of taking a step back and being appreciating the stuff that's out in the world for what it is versus everything that's out there. (38:22): And that really starts to open up your thinking to being in a much more positive place and allowing new ideas into the world. And I think then that also figures into who you want to work with as a client. So approaching industries and approaching brands that you're actually a fan of is going to help you do great work for them because of the just natural enthusiasm that you're going to have for them. And I really feel like that enthusiasm and friendship that you would have with those brands, those products, those categories and the people behind them lead to better work and lead to a better relationship and experience overall. And I think consumers see that if they're really far away from that process, but they see it and they can feel it. Someone told me once that selling is really being a salesperson. A good salesperson is really just the transfer of enthusiasm from one person to the next. (39:27): And I kind of believe that. And when you're a fan of the work that you're doing and you're enjoying the process, that enthusiasm goes through. I've made a point for myself. I've just started looking at design annuals and add annuals and stuff like that. Again, there was years where I just couldn't look at it, and I made a point for myself only look at stuff in context because then it's real on your experience like a consumer, which is great because we all know the whole design annual world of things can be a little shifty. But once you start to appreciate that work just for what it is versus the overarching in the no context, you get more out of it. And then the other thing that I've been doing a lot lately is, and you've been seeing it happening in social media, it's just gassing up other people, like celebrating other people for the success and the work that they've been doing. (40:28): And I enjoy it when people say, I really like that work. It was really exciting that you reached out to me and you mentioned that work that you saw. And so that's really cool. We should have a conversation that feels really good, and why wouldn't you want to go and do that for everyone else who's going through the same struggles and are blessed enough to get to work in a creative industry? That's one of the other things that it's not always easy, but man, it's a whole lot better than a lot of the other things that we could be doing out there. And you might as well just enjoy it, let other people enjoy it too. It's a big old world with a whole bunch of work that everybody could be doing.", "token_estimate": 840, "speakers": ["Dave Taylor"], "start_timestamp": "37:33", "end_timestamp": "37:33", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "46c91ff8-db28-4f7a-8a97-42dc22a00e08", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 16, "content": "Cole Heilborn (41:08): Have you found yourself battling with that fan versus cynic mentality?\n\nDave Taylor (41:14): Yeah, I mean, that's where it came from. I was just like, it's not feeling fun. You and I realized why it was that way. It was being really competitive with the other people, both in the agency that you're working at, the other agencies that you're pitching against, the in-house people who are working there. And you try and bolster yourself up by putting people down and it doesn't feel good. But flipping that on its head and saying, you know what? That other agency might've won this pitch because their ideas were better. Awesome. And look, that work is actually fantastic. I wish I could have done it. But then on the flip side, and it just feels a little bit better, honestly. And then being a fan of what's out in the world, you can look at things with brighter eyes\n\nCole Heilborn (42:07): And you probably end up learning more from it too, because now you're open to the piece that you're looking at and your blinders are kind of removed, and so maybe you'll learn something from it that you wouldn't have otherwise if you just dismissed it early on.\n\nDave Taylor (42:21): Exactly. And then you share that with your clients. I actually, I was chatting with Jill at Diamondback on Instagram sharing this great illustrator that I worked with a while ago, and I was like, just hire her and have her do a bike for you. It'd be amazing. And that both helps that relationship with Jill and I just as human beings sharing cool things. But it also turns me into a resource and a trusted collaborator, not just holding that to myself, but if you start to share and support other people. And I think the karmic energy of all that, not to sound too trippy on that, I think it comes back.", "token_estimate": 451, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "41:08", "end_timestamp": "42:21", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "11f81e56-3dbd-4984-95f1-a22b106c5a43", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 17, "content": "Cole Heilborn (43:01): No, well said. It is interesting why we often as creatives default to that cynic perspective when you're looking at someone else's work and some of those reasons that you just listed off, they're like, well, they only got the job because of X, or they really botched up this one element of whatever I'm looking at. We're super hypercritical of other people's work, and yeah, I wonder if that's, as you said, to make us feel better about our own work.\n\nDave Taylor (43:30): Yeah, it could be. I think any good creative is really critical of the work that they do themselves, and that's just part of progress in being a creative person. But I think as I become a little bit less critical of my own work and just let the process play out, the work ends up getting better. And yes, you have to feel good about it. It needs to be presentation worthy. You always want to feel like the next project that you're doing is the best work that you've ever done. But once you kind of get out of this almost self competitive feeling and enjoying the process of going through the steps that you know need to make quality work, it becomes a whole lot more fun. And I think the work is a whole lot better. I think the last couple years of work that I've been doing has been some of the best in my career because I have a clear understanding of what I need, what the process needs to be, what kind of information we need to gather with the client from both just a blocking and tackling perspective, developing the right strategy, understanding the wants and needs, and just taste level of that client. (44:43): And not just the client, but also the consumer as well, to make sure that it's going to be relevant to them. It's going to be different than what else is out there. So it sticks out and people will want to seek it out because it's different and notice it more, and then having a good time making things. I think there's a lot of creatives that forget that it's supposed to be fun, at least for me anyway.", "token_estimate": 505, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "43:01", "end_timestamp": "43:30", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "84846f24-6516-47a3-9bf6-a0f964609229", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 18, "content": "Cole Heilborn (45:11): Yeah, no, that's a great point. And what a great way to wrap up our time for today. I guess, any other thoughts? We've talked about a few different things, but I mean, I love the positive message at the end here, but I also think some of the tactical advice you've given earlier on just about company structure and the pros and cons and things to consider are really interesting. Any other lasting thoughts about any of those topics?\n\nDave Taylor (45:36): Yeah, I think the way that you just mentioned it I think is good because once you have the blocking and tackling stuff done, then everything else gets really fun. And so once you have your baseline figured out and you're starting to hum, everything else just opens up, becomes more fun. So if you take a football team, for example, if you have a really great running back and an offensive line in the trenches doing the hard work, you get to throw long bombs to the wide receiver and score touchdown. I don't know why I brought up football. I don't watch it whatsoever, but it seems like a decent metaphor to end with,\n\nCole Heilborn (46:14): Dave. I love that. If folks want to follow along with you or with Okay, row, where can they go to connect?\n\nDave Taylor (46:22): You could find me on Instagram at ok bro. Ok. A-Y-B-R-O or check out the website ok bro.com.\n\nCole Heilborn (46:30): Okay. Right on. Well, thank you again for your time, and I hope you have a great rest of your day and hopefully get out on the bike this weekend.\n\nDave Taylor (46:38): Definitely. Thank you so much for bringing me on.\n\nCole Heilborn (46:40): Yeah, take care. You too. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 462, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "45:11", "end_timestamp": "46:40", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "5de0c8fc-2bd6-4fee-9877-803d9ad4de59", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 0, "content": "Ben O'Meara (00:11): I think the consistency is so, so important in creating. You can't just create trust in one interaction. You have to have multiple positive touch points with any person, with any brand, with any product before you really create that relationship. Then once you have the relationship, that's where the trust comes in. That's where the loyalty comes in. That's where you feel like you're part of the community.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing Podcast. My name is Cole Hilborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo. Today I'm sitting down with Ben O'Meara. He's the VP of Marketing over at Huckberry. Ben, how are you doing?\n\nBen O'Meara (01:13): Good, Cole. How are you?\n\nCole Heilborn (01:15): Fantastic. Having a good day. Excited to chat. How are you doing?\n\nBen O'Meara (01:19): Same man. Yeah, I'm excited to be here. I appreciate you having me on. As I told you a couple days ago, I'm sitting in our new Austin headquarters breaking in our new studio, so I'm excited. My first chat in this new space is with you\n\nCole Heilborn (01:33): And it looks so good. You guys were previously in the Bay Area, correct?", "token_estimate": 425, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "00:11", "end_timestamp": "01:33", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "819f48ad-3a18-4801-8c1a-f5144edb0513", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 1, "content": "Ben O'Meara (01:37): That's right, yeah. We were founded in San Francisco. We still have our office in San Francisco. Half of our employees are still based there, but during COVID we decided to make the move and open up a new office in Austin. Austin is and will become sort of the official Huckberry headquarters. We will continue to maintain a presence in San Francisco. Again, that is our home and our birthplace. We've also got another office in Columbus, Ohio where we do all of our fulfillment and operations, and then we've got an office there as well with a number of CX and operations employees.\n\nCole Heilborn (02:10): Are you neighbors by chance with Yeti or Howler Bros?\n\nBen O'Meara (02:13): We aren't physical neighbors, but in a town like Austin, and honestly, it's one of the reasons we moved here, not just because of those guys, but they've been friends and brand partners of ours for so long. We knew the city was a place that we had a great customer base, a great brand partner base, but as you can imagine, you are within one degree of separation from someone at Yeti or Howler anywhere in Austin, which is a good thing for guys like us. So they have been among many other brands and friends, incredibly welcoming and warm since we moved here a few months ago.\n\nCole Heilborn (02:48): Yeah. Well, I hope with all the recent changes with the move and everything, you have been able to find time to get outside and have some fun. Before we get into it, what do you enjoy? What are your hobbies? What are your passions?", "token_estimate": 385, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "01:37", "end_timestamp": "02:48", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "783340fd-075e-4d90-b886-780c6c743433", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 2, "content": "Ben O'Meara (03:01): It's a good question, and coming to Austin, one thing that I've loved, it's a very active city is, and so many of those great brands that we just referenced are such great examples of the lifestyle and the adventurous spirit and all that Austin has to offer, but I'm a big trail runner, so it's been really fun to explore the city and the surrounding areas, the hill country in that capacity. For anyone that's spent time in Austin, there's amazing trail systems downtown along the river. There's a number of really cool sort of canyons along rivers that have incredible runs, and then at the end you can jump to the river and cool off, which is needed, especially in the Texas heat and this summer. So spending a lot of time doing that love being on the water, so just got a paddleboard hoping to get out there a little bit more. I have an 18 month old, so my recreational time is limited, and what I do has changed a little bit, but luckily my daughter loves to be outside. She loves to hike, loves to explore, so it's been fun also bringing her along for some of those adventures. We're obviously not running together with that baby backpack, but doing a lot of hiking, a lot of trail running, getting into gravel biking. (04:18): We'll see how much time I can devote to that, how much my wife is not as excited about that potential new hobby\n\nCole Heilborn (04:25): Just because of the time suck.\n\nBen O'Meara (04:27): Time suck. Yeah. I've got enough sort of hobbies and gear as you can imagine, working at Huckberry. So it's also like a space thing, another thing for our garage. But yeah, those are kind of what I'm into right now.\n\nCole Heilborn (04:40): Nice, nice. Well, I'd love if you could give us a quick introduction on Huckberry and then a quick maybe background info on your job and how long you've been with the company.", "token_estimate": 465, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "03:01", "end_timestamp": "04:40", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "5ba5a679-fab6-4473-8d33-e964df8e22f9", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 3, "content": "Ben O'Meara (04:52): Sure, yeah. Huckberry, as we briefly mentioned, was founded in San Francisco 10 years ago. Huckberry is, we're a retailer. We're online. We were started online, and I think going into where Huckberry started and where we are today still foundationally, the core of Huckberry is product curation and content and storytelling. And so how that comes to life from a product standpoint, really the inspiration behind Huckberry was Andy and Rich, the two original co-founders and still founders of the company today, saw this void in the market, if you will. You hear the term like scratch your own itch, and they're sort of the epitome of that in all the right ways. They were guys who lived in the city. They were both working nine to fives. They were both working in finance, but on the weekends craving adventure, whether that was skiing in Tahoe, going mountain biking in Marin, hiking, exploring the city, trying new restaurants, traveling, and they obviously loved the outdoors, but also appreciated everything that a city has to offer and the things that you do, whether it is in that nine to five window, but really that five to nine experiences after work. (06:10): So the original inspiration behind Huckberry from a sort of product curation standpoint, you have the outdoor traditional brands and then you've got the, let's say, more style forward everyday fashion brands, if you will. And those are two very sort of generic ends of the spectrum. Any and rich love to be outdoors, they love to travel again, they lived in the city, they cared about the things that they bought, what they're wearing to work, what they're wearing when they're going out with friends, but they also weren't necessarily interested in the most technical on the outdoor side and the most stylish, trendy fashion forward things on the other end. And from an actual experience standpoint, this was early on in sort of the rise of e-comm, if you will. Traditional retailers were still really dominated by big box department stores and physical retail stores, and then obviously Amazon on the other end of the e-comm spectrum. (07:10): So they saw this opportunity that kind of married their love for the outdoors and adventure, but then their love for the city and all the things that lifestyle implies and provides and wanted to create a place where you could find brands that lived in between those two sort of spectrums that were functional and high quality, but more versatile. And so the idea for Huckberry was born. And I think the other really important piece to that all was this. The stories behind a lot of the smaller brands. Again, back then, a lot of the cool smaller brands didn't have the ease in which the world of Shopify and e-commerce is now created to get their messages out and connect with customers. And they were really inspired by a lot of the smaller cooler regional brands in their travels to other cities they'd experienced and met and wanted to create a place where you could learn about them and find those products on a one sort of centralized platform, if you will. So taking that combination of smaller brands with story and brands that spoke to people that loved the outdoors, but also loved living in the city, that was where Huckberry began, and still very much is foundational to where we are today. We carry everything from traditional outdoor gear to incredible leather shoes made in Italy, and it can be a four letter word overused these days, but that sort of lifestyle, the nine to five during the week, and then the weekend adventurer.", "token_estimate": 895, "speakers": ["Ben O'Meara"], "start_timestamp": "04:52", "end_timestamp": "04:52", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "9f19dc98-2a70-4b20-9cf9-fac5244cce7b", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 4, "content": "Cole Heilborn (08:58): Yeah, yeah. One brand that I feel like fits that really well that we've had on the podcast in episodes past is Peak Design. I feel like they straddle that really well between the Urban adventure and the Outdoor Adventure.\n\nBen O'Meara (09:13): Exactly. And they're a long time brand partner of ours, and they were our neighbor in San Francisco, so they absolutely exemplify that. Another guest of yours, a good friend Rick Wittenberger from Howler, and they have that same sort of ethos where they love adventure, they love getting outside, but there's a approachability and a creativity and even style perspective that these brands including our own want to infuse and the things that we're wearing and the gear that we're using. So that's absolutely a shared DNA for sure.\n\nCole Heilborn (09:46): Yeah, and your job, paint us a picture of what that looks like.\n\nBen O'Meara (09:50): Yeah, I oversee creative content and sort of brand broadly, so I work really closely with our creative team on the visual representation of Huckberry and the brands that we work with. From a content side, we've got a pretty robust journal putting out a lot of content, some tied to products, some that is more a traditional sort of magazine like approach where we're talking about topics and interests of our customer that are part of, again, that lifestyle but aren't explicit to a product. So we've got a great team of writers and managing editors that are constantly coming up with new ideas and things that we should be talking about and bringing to life. And then from a brand perspective, which kind of ties everything together, working really closely with our product team on the brands that we're working with and our collaborations and some of our larger marketing initiatives. We're getting into TV ads and advertising campaigns across new channels and verticals. So kind of touch anything that the customer sees and how it gets brought to life, I think is probably the most simple Broadway to describe everything that I do.", "token_estimate": 511, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "08:58", "end_timestamp": "09:50", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "b214768b-ee37-46cc-8b24-1d77a2088c94", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 5, "content": "Cole Heilborn (11:00): I think that's a fairly common default answer for most folks on this show. It's pretty much anything falls under your guys' job descriptions,\n\nBen O'Meara (11:09): And I love that. I started early on in Huckberry, so I joined Andy and Rich and the crew eight years ago now. So the cliche but true, I was in a garage and my first interview with them was in a grocery store. They didn't have an office, and back then we did everything. And so I was one of the original buyers. I had no buying experience, but I guess I had a pretty good nose for brand story and what I thought our customer might like to see and learn more about. And so that's something that I still love and again, that connection to the product and the story, and now I get to work with incredible creatives and writers and everyone in between to bring those product stories to life and those community stories to life and those people stories to life. So I feel incredibly lucky to sit in the position that I do.\n\nCole Heilborn (12:00): And how many brands do you sell? And to be clear, you guys aren't picking necessarily flagship products from these brands. You're picking some of the products that are maybe under the radar, correct?", "token_estimate": 307, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "11:00", "end_timestamp": "12:00", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "75419205-f0ab-4d48-9fc2-bb37678bf9cf", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 6, "content": "Ben O'Meara (12:12): Yeah, yeah, absolutely. And I think that's an important point that I missed talking about some of the important pillars to the idea of Huckberry was this idea of discovery. And I did talk about newer smaller brands, and so that's from a brand level obviously, but also from a product level. So we work with the Patagonia of the world, we work with Danner and Filson and some of the more recognizable, reputable, respected brands and sort of the outdoor men's lifestyle space. And we certainly carry their core products, but something for Huckberry because we've got this reputation and it's part of our sort of brand promise is discovery, introducing you to new things. We try to find things that maybe you don't see at a larger big box store that everyone has seen and everyone does own pulling things off the line that maybe sits in a more specialty retailer but would make sense as sort of a feature on Huckberry. And then we work with those brands also on special smu. That's really what gets us going when we can actually partner up and create a new product opportunity with a brand that and love but cannot be found or sold in other places.\n\nCole Heilborn (13:20): You're talking about the collaborations that you do,\n\nBen O'Meara (13:22): Collaborations and just exclusives, like bring in products off brand. So collaboration's, the sort of tip of the spear where, and maybe we help design and develop a new product, but a lot of the things that we do is also seeing things that a brand is already making. And we're lucky we're at to scale now and we know our customer well enough that we can take things completely off of brand's line and so they can't sell it to other retailers, and it becomes a hub exclusive, and that's such an important part of that discovery process. You've never seen this product before because we're the only ones that's ever sold", "token_estimate": 472, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "12:12", "end_timestamp": "13:22", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "453b73b4-3f1e-4f64-8f3c-692ea221e868", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 7, "content": "Cole Heilborn (13:52): It. Interesting. So there's a lot of things from what you've just mentioned that I'd love to dive into. But before we go deeper, I think something we should address is how you guys approach storytelling through all of this, because that's kind the bedrock I feel like to a lot of the piece you're describing. So how do you weave that into everything that's done at Huckberry? Maybe that's a really big question.\n\nBen O'Meara (14:15): It's a really big question, but it's also, I think it's a big one and that it touches everything and it is so core to our brand, but I think if you also simplify it and not in the sense that it's easy and simple to do, but it is, like I said earlier, it is so foundational to Huckberry. So it's really at our core, this idea of storytelling has been one of the number one product value promises that when Andy and Rich created this brand was going to be consistent from then until however long the brand was alive. And so when you think about how that then gets brought to life at the very beginning, how we talked about brands was different than you saw in other retailers. That was our promise to everyone from day one. We didn't have a big budget. Andy and Rich bootstrapped the business for the first six or seven years, but what we did bring to brands was this point of view in this editorial lens to their story and to their products that other retailers were not doing at the time. (15:24): And so that was quite literally how we built Huckberry, how built our newsletter was telling these stories of these brands. So that was just how we did things, and that becomes just a muscle that becomes so natural as you continue to build it and grow and add new people. That's just how the business operates. That's our business strategy. And so when you have that foundation, it makes things, I don't want to say easier, but it's just what we do. And that's when, I don't mean to oversimplify it, but that is what we do. And everything from a product page, we're really intentional with how we talk about products, making sure, of course we hit on the important features and materials, but how we describe that product has more of a voice, more of a point of view. We think about the customer and what they're going to be using it for, how Huckberry would recommend using it and what we're inspired by based on this product and this brand story. (16:17): So yeah, if you think about from a product level, our product pages, we consider a part of the storytelling pie. And of course we want to make sure that we are hitting on the important features and materials and how something's constructed, but our copywriters do such a great job of taking all of that information, all the ingredients, and contextualizing that in a way that is in a huckberry voice. It's relatable, it's approachable, but also putting the customer in the shoes of actually using this product. So I think from that sort of first touch point, if you land on a product, you feel that voice and then as we've continued to grow and scale and you find these incredibly inspiring stories and it's like, wow, there's a lot to unravel here. We can't describe all of this in one email or one product page. That's where our journal comes into play. (17:07): That's where our email comes into play. That's where our new channels and video development and podcasting will come into play. And I think that's the beauty of Huckberry. Again, going back to we want to be working with brands that are doing things a little bit different, that are focusing on quality, that are differentiating from all of the sort of mass that's out there. And when you have these amazing people and products, it makes our jobs, I don't want to say easy, but it's an incredible group of ingredients and amazing stories to start with. And then it's our job to figure out the best ways to unpackage those stories.", "token_estimate": 977, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "13:52", "end_timestamp": "14:15", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "76ba28bd-2faf-4f88-8f0e-148c1e15227d", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 8, "content": "Cole Heilborn (17:45): You mentioned that part of the goal is to figure out how to differentiate. Is that why the founders have placed so much emphasis on storytelling or was storytelling just the natural way to talk about things as you entered the world?\n\nBen O'Meara (18:03): I think again, going back to that cliche, but scratching your own niche, that's how they wanted to be talked to. They didn't want a bunch of marketing jargon and cliche sort of copywritten taglines. They wanted someone. I think one way that we think about our voice and our content in a lot of ways is you're sitting down at a bar with a friend and they're telling you about a cool new bag that they bought, or you ask them, those are really cool boots, where are they from? And sort of keeping it real is one of our brand values and it's a tenant to our sort of voice. So it was something early on that Andy and Rich and all of us want to see and feel when someone's talking to us. And the more that we did it, the more we realized it also makes a stronger connection to our customer, our community. It creates trust when you do have that, making sure that you hit on all the important points and you give them the details. We've got a really smart customer base. They want to know how things are made and where they're made and what the materials are made of. But then making sure to contextualize that in a way that is also relatable and thoughtful to them, it creates that greater bond and that greater trust.\n\nCole Heilborn (19:21): Do you feel like people these days are tired of the marketing jargon and they're just looking for essentially a friend to be like, Hey, this is what I use, this is why I like it?", "token_estimate": 424, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "17:45", "end_timestamp": "19:21", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "64ffc2a5-b040-4337-82cf-79e4d61607cd", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 9, "content": "Ben O'Meara (19:31): I think so. I mean, I'm obviously biased, but I do feel like that. And I think the combination of there's so much choice out there, and that was again one of the origins of Hucker at the time. There's a lot of choice, there's a lot of amazing brands, but there's also a lot of crap. Let's create a place where we can curate that. That's a really important part of our strategy is the curation of brands, but also the curation of products within those brands. So I think that combination of distilling down what we think is the most relevant and what we think is cool and what we think you should know about, and then combining that with actually explaining to you our point of view there. I do think that that is something that I don't know is needed more. I do think people are tired of getting hit up with the same ads that follow the same format, that say the same thing, and there's a reason for that. And we have an incredible team and strategy in our performance world, but we try to insert our brand voice into those and not just follow the formula, not just follow the algorithm if you will. Use the data, know what's working, obviously it's an important part of the pie, but making sure that the brand voice and the brand identity is consistent through every touchpoint.\n\nCole Heilborn (20:50): So there's other product curation retailers out there, but is story the thing, the perspective that I guess you guys take, do you think that's what set Huckberry apart from a lot of other similar models?", "token_estimate": 382, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "19:31", "end_timestamp": "20:50", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "f6fec239-3530-4d7c-87a2-14759725898a", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 10, "content": "Ben O'Meara (21:04): Yeah, yeah, definitely. I think again, that was when Andy and Rich were first hitting the trade shows going to or and some of the New York trade shows back in the day, they didn't have a website. I remember some of the first trade shows that I went to and we were much, much smaller and no one knew who we were. What we sold them was our newsletter, was our content, and we're going to tell your story in a way that has not been told. Of course we're going to sell your product, but we're also going to work as that friend who is reaffirming your brand and telling your story in a way that lifts your brand up and is great marketing frankly for them. So that's always been the promise, and that has been, again, what has I think set us apart and you're now seeing content strategies and storytelling. (21:55): It is kind of required at this point in the game, but because we've been doing it for so long, I think it has become again, that muscle and that trust that people do continue to look to us for. And again, we've got such great data and insights and we've certainly tried a lot that hasn't worked. And all of that allows us to continue to, I think put out really interesting story and content and have a really strong perspective on the products and the brands that we're working with. And it is about trust. And when we do say, you should pay attention to this brand, this is a really cool brand, this is a great product, this is a great story. And then you decide to trust us with that, and you buy something, you read something and we come through with that promise and then you come back and that happens again. I think that is also one of the pillars to Huckberry in our success to this point. We've got an incredibly loyal community. Once we get a customer in, our retention with that customer is quite high.\n\nCole Heilborn (23:03): So that loyalty aspect is really interesting. Why do your customers become so loyal?", "token_estimate": 488, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "21:04", "end_timestamp": "23:03", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "2cc1a120-e452-49bd-9b9b-97184446404f", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 11, "content": "Ben O'Meara (23:08): That's a good question. I think it's consistency first and foremost. Not to overgeneralize, but you can say that you're really good at something or this is the best x, y, Z product, and the next reaction is, okay, well either you read it or you got the product and was it true? If it is true, you're more likely to go back for a second time and then a third time and then a fourth time. And so I think because we are so focused on the quality of the brands and the quality of the story and the obsession of our customer, what they want to see, what they want to read, I think those interactions with our brand, whether it's your first one or your third one, it is consistent to what brought you in there and got you interested in the first place, if that makes sense. A lot of people that say, this is the best X, y, z, and you should read this, and then you get in there and you're like, this product is crap, or the information that's actually in this article is bullshit. You just got me with a catchy tagline. And I think again, at our core it's all about quality, quality, quality, quality, and that's the quality product. Quality brand and the quality story and content,\n\nCole Heilborn (24:32): But then showing up consistently for every,\n\nBen O'Meara (24:34): But you have to do that consistently. Exactly. Constantly tinkering and iterating. But I think the consistency is so, so important in creating that you can't just create trust in one interaction. You have to have multiple positive touch points with any person, with any brand, with any product before you really create that relationship. And then once you have the relationship, that's where the trust comes in, that's where the loyalty comes in. That's where you feel like you're part of the community.\n\nCole Heilborn (25:04): I think I read somewhere that in the restaurant industry, it takes three successful experiences at a new restaurant before a customer becomes a loyal customer of that restaurant, which when you consider what it would take to get three out of the park experiences at a restaurant, that could be tough to hit.", "token_estimate": 531, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "23:08", "end_timestamp": "25:04", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "e93f0c55-ed6f-4444-8dd1-0c8a7a085dcb", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 12, "content": "Ben O'Meara (25:27): And I think an important part of that too, and I don't want to sound like we do everything. Like I said, we make a lot of mistakes. We've made a lot of mistakes, we continue to make a lot of mistakes, we've gotten a lot better and we make a lot less of them. But going back to that point of having an approachable voice and a realness to your brand, it's much easier to rectify those mistakes. If you're real, you own it and you follow up with a great experience after the fact. Sometimes our best customers actually come in, they bought something for the first time, it didn't fit, but then they interact with our customer experience team and they're like, holy shit, this is a different experience. I talked to a real person and they got on the phone and they talked me through other options. And that experience is also a positive experience and a consistent experience. So I think it's also what you do with the negative interactions, and that's also a big focus of ours is making sure that when we mess up one, we own it. And two, we are incredibly proactive in finding the right way to fix it.\n\nCole Heilborn (26:22): Yeah. What other ways have you guys screwed up? Any big blenders that you can think of that you've learned from?\n\nBen O'Meara (26:31): There's so many. That's probably a whole podcast. We've actually joked about that we could create a podcast on the mistakes that we've made. There's a lot of success story podcasts, but\n\nCole Heilborn (26:40): I think people would love that.", "token_estimate": 381, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "25:27", "end_timestamp": "26:40", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "c16e8210-41d1-4fd0-9344-975bb3daf2c2", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 13, "content": "Ben O'Meara (26:41): I agree. Here's an example from a product curation standpoint, I think one of the challenges and sort of the watch out if you will, as sort of a lifestyle brand that can play in a lot of different places, and again, as I said, we can have the really rugged traditional heritage outdoorsmen, but then we've got the more modern EDC minimalist traveler in our customer base and in our brand identity. And you can start to think, okay, what else can we do? We can be everything to everyone. And so there was a point where we went pretty hard at dress wear nine to five buttons up and suits, and we can own the entire closet from going into the office and wearing a suit. And obviously the world has changed in terms of what you wear to the office or will wear to the office again. (27:36): But we went pretty hard at a more nine to five element to Huckberry, and our customers came back to us and they're like, Uhuh, we of course appreciate a lot of the products that you do sell that I may take to work the Fils and Briefcase or the more versatile five pocket Chino, a great pair of boots, but the button up and the suit that's not Huckberry. Your brand is rooted in adventure and versatility and a number of those other things that we've talked about. And it was one of those, we spent a lot of resources, content strategy, we got our buyers bringing on a bunch of new brands and obviously investing in the product and it was just a good reminder that we can play in a number of different places and personas and styles, but don't lose your brand identity and what's core to, that's why people are coming to you if they want to suit, they can do that in another place that is that expert. So that's definitely one.\n\nCole Heilborn (28:40): Yeah. And was that feedback, how did that come across? Was that social? How'd you hear about that feedback", "token_estimate": 466, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "26:41", "end_timestamp": "28:40", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "cab0aa16-45e4-44c7-92bb-ddf049b0f575", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 14, "content": "Ben O'Meara (28:47): First? Sales, it's like this isn't really selling, this isn't quite working. But then you get that anecdotal feedback, those different touch points, you start hearing people chiming in on social when you're posting a picture of a guy in a button down in a tie and they're like, that's not huckberry. You have longtime customers writing in and saying, Hey guys, not really what I'm interested in. I'd like to see more of X, Y, and Z. So it was a combination of things. I mean first and foremost it didn't sell, and then you start connecting the dots with some of the anecdotal comments here and there, customer experience writing in. So it was a variety of things. I was just say, and also it was one of those we got really excited about it, like opportunity, opportunity, but then once it went live and we're sitting back and looking at the brand and you have all these great images and great brands that we've spent years curating and telling stories around, and then it just didn't feel right. So it was an interesting one. Now we certainly not to keep going down this rabbit hole. We certainly sell an Oxford shirt and we sell really cool unstructured blazers and even fun linen suits from great brands, but even those are more connected to the Huckberry brand identity. It's a smaller brand, it's more versatile. They're typically things that maybe you're wearing to more of a destination wedding or a more casual office in a more creative space, but that nine to five buttoned up loafers did not work for our guy.\n\nCole Heilborn (30:30): What a great example of your consumers or your audience or really your fans, I guess in your case kind of checking you guys and saying, no, that's actually not who we think you are. I don't remember who said it, but a great brand is measured not by how the brand describes itself, but by how its people describe it.\n\nBen O'Meara (30:52): Yeah, was that Ogilvy said something similar and maybe it was him, but yeah, absolutely. Yeah, absolutely. And again, we have a lot, we were all more traditional nine to fivers and we have a lot of more traditional nine to five amazing customers, but just what they come to us for was not that.", "token_estimate": 549, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "28:47", "end_timestamp": "30:52", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "377b6a79-b161-4e33-8c81-85f123f2e22c", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 15, "content": "Cole Heilborn (31:13): Let's talk a little bit about your collaborations. So you mentioned there's kind of two camps where you collaborate with an existing product and maybe do a cross branding or something, or you guys create an exclusive product. A recent collaboration you guys have done is the Coors Banquet project Fill us in. How did that go?\n\nBen O'Meara (31:31): That was a fun one, and that was I think all of the different components that we've talked about, the storytelling, the content, the product, the exclusiveness. That was one of the best examples of wrapping all of that in one integrated campaign. So I think that different components of that. Of course Banquet has this incredible archives of old logos and amazing old branding and they've got a cool heritage in Golden Colorado and they let us have full access to the archives and designs. And so our product team was able to design a bunch of really cool exclusive and hats and we did a really cool custom boot. We did a cool cooler. And so from a product standpoint, there was an exclusivity angle. Obviously these were special. Once they were sold and gone, they were gone. They were also really interesting product. And so they checked all the important product qualities and pillars that we stand for. (32:34): And then from a content storytelling standpoint, we put together this really interesting video series where we profiled three different individuals who sort of in their own worlds in ways represent adventure and creating access to adventure in their communities. And so we had this incredible graphic artist and surfer in Santa Barbara and does a lot of really amazing, important work in his community and getting kids into the water that maybe have not had access or felt welcome there. We worked with a former hotshot firefighter and his efforts in conservation and documenting forest fires and sort of the challenges and devastations that obviously we're seeing across the west right now and really telling their stories as sort of individuals who again represented venture and what they do to make venture more accessible to their communities. We worked with this incredible fly fishermen and comedian in Denver, and so again, similar type approach working with his communities to get kids that don't have access to fly fishing and have felt included in fly fishing out onto the water. So it was a really cool cohesive campaign that tied together really interesting product with really thoughtful storytelling and involving the communities and the places that we profiled.", "token_estimate": 641, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "31:13", "end_timestamp": "31:31", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "18c4eb80-f759-4794-a4de-c3f481c6de4f", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 16, "content": "Cole Heilborn (34:02): What are the intentions behind the collaborations?\n\nBen O'Meara (34:05): Just broadly?\n\nCole Heilborn (34:06): Yeah, why?\n\nBen O'Meara (34:07): I think there's a couple different reasons. I think from a product, maybe this isn't the sexiest answer, but collaborations are exclusive to your brand, and so they allow you to one, have that moat and it's a product that can't be sold in other places, and you need that when there's a lot of competition out there. It also allows you to insert the information and data that you have from your customer base. Again, serving the customer best. We know the colors and the styles and the vibe that our customer loves most. We're able to influence that product and create what we think is an even better product catered to our customer. So from a product standpoint, that's a really important piece to the collaboration strategy. And then broadly, I mean, collaborations are a really important marketing channel. You want to work with brands to elevate your brand. (34:59): You are who you hang with, and so that's exposure into their audiences. That is brand association. So I think from a marketing side is that important, top of the funnel, brand awareness side of things. And for a discovery brand that focuses on content, the best collaborations come with a story first, and that story influences the content and the product just like that cores example. And so it just makes for a really interesting campaign and brings delight and interest and sort of a moment to the Huckberry website, the huckberry email, the huckberry content, and that's all in service of our customer.\n\nCole Heilborn (35:39): Is the journal kind of what sums up all of the content behind Huckberry or how does that work? You have an extremely robust journal that I think also connects to your email campaigns. So how does that fit into this equation?", "token_estimate": 473, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "34:02", "end_timestamp": "35:39", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "9c3dadda-5b91-427c-ae8d-b6041e9e33d3", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 17, "content": "Ben O'Meara (35:56): Yeah, I mean it fits in every single touch point possible. So we have product specific content on our journal, so that's a deeper dive into how something's made, where it's made the story behind the founder. And so it's a great opportunity to expand on the product or brand storytelling of the things that we're selling. On the other side of the equation, we've got what we call interest-based content, and that's with a more sort of editorial media lens, if you will, and understanding what our customer is interested in beyond just the products. Maybe it's the things that they're doing with the products, but things like whiskey and cabins and adventure itineraries and beer recommendations and stories of entrepreneurship and inspiring stories of epic travels and sort of adventure. So that part of the equation's incredibly important to continue to again, build the sort of brand and the lifestyle, but also from a customer standpoint, we don't always want to feel like we're selling to you. (37:02): We don't want you to come to Huckberry just because you have to buy something. We want you to come to Huckberry when you need something and when you want to discover something, if you want to browse or you're shopping for a trip or with intention. But on the flip side with our journal and how much content we do put out, that crosses so many different types of interests and categories. It gives our community and customer base a reason to continue to come back and read something and learn something. So the journal's always been part of Huckberry, but as with any company and you're scrappy and growing and having to reprioritize how much time and resources you're spending on things, it's gone through multiple sort of iterations where there was a point where we're doing one article a week, there was a point where we're doing one article a month, there was a point where we're doing three articles a week, but we just kept doing it. And now we're at a point where we've got the data and we've got the confidence frankly in what our customers want to see more from us of to be putting out. We put out a journal article once a day at a minimum, and at least 50% of that has nothing to do with a product that we're selling. It's more the lifestyle, the interest of our broader customer base,", "token_estimate": 581, "speakers": ["Ben O'Meara"], "start_timestamp": "35:56", "end_timestamp": "35:56", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "4fd9409c-9438-4c37-a126-0a8a60022ef7", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 18, "content": "Cole Heilborn (38:17): Just that ability to add value to\n\nBen O'Meara (38:21): The\n\nCole Heilborn (38:21): Audience.\n\nBen O'Meara (38:23): In my mind, I always want someone to be able to come to Huckberry and walk away with something, whether that's a great product or a great piece of content or a great new skill or you learned about someone interesting and you go off and you do your own deep dive and go down a rabbit hole on something. But I think we talk a lot about our content needs to be actionable. It doesn't mean everything has to be a how to and a recipe, but we do want it to be sort of a door into sort of a new interest or a deeper dive into something that you can learn more about.\n\nCole Heilborn (38:53): So to have a diverse set of content that is constantly opening doors for people, that must mean you have a pretty robust group of writers, editors who are out in all sectors of the world.\n\nBen O'Meara (39:08): Our editorial team will probably laugh at my answer. We've got a pretty small nimble team that is internal, and I think what we all benefit from is we're surrounded by incredible people and stories in that Huckberry universe. The brands that we work with are ambassadors, the people that we get introduced to. So we have no shortage of ingredients, if you will. I think the real challenge for our editorial team is prioritizing what to do and what to write. On the sort of more practical side, we definitely have a great network of freelance writers that are part of our community. We've got a great group of ambassadors that are constantly pitching us on story ideas. So it's also one of the areas that we're investing more into and building out our content arm and investing more in not only writers internally, but bringing in more editors at larges that represent different expertises and are in different places of the country with a different sort of lens and pulse on what's going on. But our team is still pretty small and pretty nimble, but we're just very fortunate to be surrounded by incredible stories and inspirations constantly.", "token_estimate": 519, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "38:17", "end_timestamp": "39:08", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "45936712-ebb7-4aa3-8e98-17a8728a26c0", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 19, "content": "Cole Heilborn (40:24): And let's talk about email. You mentioned email from day one has been really important. I love your emails. I see them and I'm like, oh, sweet, I'm excited. Talk me through the email portion of all this.\n\nBen O'Meara (40:38): The email is the bread and butter of Huckberry, if you will. It is the channel that is built huckberry in many ways, and I think the email represents everything that we've talked about packaged in one newsletter that hits your inbox Tuesdays, Thursdays, and Sundays. It's a combination of a curation of brands. You're never going to open an email and it's going to be one single brand or one single type of brand. You're always going to get an assortment of brands of what's new and what's interesting and what's relevant to the season or the moment. So there's always something that's new and interesting from a brand and product perspective. And we use that email as sort of that appetizer to introduce you to the story of that brand or of that product. So there is a decent amount of editorial in these emails more than you see in a lot of e-commerce, more transactional emails. (41:31): There's paragraphs that are featured throughout. And then we incorporated, you mentioned this content throughout that email, so there's always a journal article at the bottom of the email, and sometimes that journal article is tied to a product or a campaign above. More often than not, it's something completely separate. It's something, again, interesting and relevant that our editorial team thinks is worth reading, worth learning about. And then we also, I think breaking down the DNA, so we've got the product and the product curation. There's always newness, exclusives, there's consistency in every single email that there's going to be variety, there's always going be content. And then another really important piece to our email is sort of the bottom half of the email, which we call diversions. And then see you out there and diversions every single email we feature three articles or three pieces of content, video, podcast, a lot of written articles that link off to other people's websites, other people's contents, other people's stories.", "token_estimate": 549, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "40:24", "end_timestamp": "40:38", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "d78115a8-e9b3-4d55-8bea-187f7eb34a1c", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 20, "content": "Cole Heilborn (42:34): That's usually a no-no,\n\nBen O'Meara (42:36): A no-no. Right? Yeah. Early on, a lot of people tell us that, and this was giving credit to Andy and Rich. I mean this was something that, again, they wanted to create a newsletter that they wanted to read, and I love sharing interesting articles that I find interesting with my friends. We share a lot of the same values and share the same interests, so how can we incorporate that into an email? And so that's what diversions represents. And we had a lot of people tell us, you should not be sending links off your own channel to someone. But what that does is we went back to the trust and consistency. There are people that open our emails just to see our diversions. They want a good read, and that's okay because they're opening every single email. And then eventually when you need something or you want something, you're probably going to give us a try and buy something. (43:25): So it creates that we're creating value whatever touchpoint you're coming in with. And so it also gives us a good data point on what our customers are interested in, who clicked most on which article. And it's like, huh, we didn't think that that necessarily was going to be an interest, but is that something that we need to provide more content and more context to? So it's a great data point for us as well, but first and foremost, it's just we love sharing interesting stories, whether it's product or content, and let's make sure that we're doing that, especially if it's other reputable content magazines, creators that we take inspiration from that we want to work with. We want to be that platform that shares good things. And then we've got our CU out there, which is the classic email sign off, which is that inspirational window into something epic and aspirational. (44:15): Everything can't be top of the mountain and amazing adventure mobiles, but we all need that once in a while. And so to see you out there is just a nice little sign off that if you're sitting at your desk at nine in the morning and you're about to jump into a spreadsheet and you look at some amazing photo, even for that moment, it kind of takes you to a different place. That's what it's there for. And it's also an opportunity for us to again, feature a lot of our friends, ambassadors, the work that they're doing. A lot of our own photographers. We've got such an incredible group of creatives in our sort of network. So it's also a nice sort of nod to people that we work with and people in our own sort of huckberry world here.", "token_estimate": 645, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "42:34", "end_timestamp": "42:36", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "f1f4cd60-0fa2-495f-8642-5e9bad784101", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 21, "content": "Cole Heilborn (44:53): A couple episodes, I had Lloyd Vogel from Garage Grown Gear on the show, and we were talking about email, and I think you mentioned this as well, but he said Email is one of the last channels that's intact. It doesn't have a filter. I mean other than a spam filter, but there's something so much to be said about having that direct communication with your audience.\n\nBen O'Meara (45:17): There's no algorithm that can change, and absolutely it is an owned channel. It you're seeing emails is kind of back in trend, if you will. I can't believe I'm even saying that, but you're seeing the rise of Substack and COVID brought back a whole new group of people that are writing and getting out their sort of content and their perspectives, and it's the equivalent of what Spotify did for brands. The idea of people putting out their newsletters to, whether it's a niche community or an expression of their interest or expertise, it's just such an important channel. And again, it is quite literally what is Bill. I mean, that is when we were talking about storytelling, it was storytelling in our email, and that continues to be that I guess gold standard for us. And so it is so important and to consistently do it well, not only the content within, but as I mentioned also there's intention behind, we send it Tuesdays, Thursdays, and Sundays at the same time every week. (46:20): We don't want to spam you. You're not going to get five emails from us in a week. But it also creates hopefully a little bit of that anticipation. It becomes part of your morning routine. We hear a lot of customers like Can't wait to read my Huckberry email. And so we also send it at eight in the morning because previously that was a commute time, but it's also a time where we all spend warm. You're drinking your coffee, you're checking email, you're not quite ready to dive into anything. So I think there's a lot of different tactics and intentionality into what makes a really good email and why people open it. But yeah, it is kind of going back to that point that you made. It's an own channel. It cannot change. It means you have to invest in it if you want it to be good and you want people to continue to open it, that's the other edge of the sword. But if you invest and we invest a good amount into it, it's the most profitable from a financial standpoint, but also from a brand building standpoint.", "token_estimate": 604, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "44:53", "end_timestamp": "45:17", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "7fcc7a6b-c66a-44b2-96d1-ca35d582e137", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 22, "content": "Cole Heilborn (47:19): But email, I mean it seems old school.\n\nBen O'Meara (47:22): Yeah, totally. Yeah.\n\nCole Heilborn (47:24): But it works.\n\nBen O'Meara (47:24): It works. Yeah. Think about the change in our own, how we use social media. I don't go on Facebook anymore. I don't use Instagram nearly as much, but I'm always in my email because professionally I need to be there and it's still the best way to stay in touch and send pictures of my daughter to my mom. And you can do a lot through text, but email's the most consistent and the most sort of trustworthy, if you will. So it is old school, but it's also, it's as relevant as ever.\n\nCole Heilborn (48:03): And was email chosen back when the company was started because it was the most accessible, or did you guys see, oh, email is going to be a thing we should invest heavily into it or?\n\nBen O'Meara (48:15): Yeah, that's a good question. I don't want to speak for Annie, and I don't know if they necessarily saw the sort of roadmap as email is going to be the thing, but I do think one, it was free in a way. Again, it's your own channel. You have to invest time and resources and obviously pay for whatever platform you're using, but once you get it going, it's a very cost effective way to get your message out there. And again, it was one of those, there wasn't a lot in the toolbox yet in terms of negotiation offerings from Huckberry. It was like we're going to put together an email, and newsletters was still relatively new. Again, this was 10 years ago, and so this is going to be commerce, but in a newsletter format. And again, it's going to be consistent and there's going to be story, and we're going to invest a lot of our time in making sure that we get a lot of people to sign up for this email. And that then is used as sort of a negotiation, if you will, when a brand that's never heard of Huckberry is like, okay, yeah, you tell me that you can tell a good story, but and who's reading it. And email's a very easy place if you can get people to sign up for it that you can point to.\n\nCole Heilborn (49:28): How do you get people to sign up for it?", "token_estimate": 533, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "47:19", "end_timestamp": "49:28", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "3530311b-d59e-40a1-8fa4-183e3bc7ce39", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 23, "content": "Ben O'Meara (49:31): Yeah, it's a combination. I mean, at this point there's obviously lots of different strategies and ads that we run and Hard gate, soft gate testing, all of those sort of technical things. But early on we relied a lot on our brand partners, like the early brand partners, you sort of trade. We will invest in this content and this storytelling if you tell your community that you're on Huckberry and send them over to Huckberry and sign up for the newsletter. We were also pretty early in affiliate marketing when we were really, really young. People like Art of Manliness and Outside Magazine took a chance on us and liked the vision and what we were doing and would shout us out and recommend the Huckberry newsletter. It really was a lot of word of mouth, organic recommendations to start, and then that slowly starts to snowball, and then you start building the strategy and you start building the affiliate team and you start building the email acquisition strategies, if you will. But it was a lot of, you scratch our back, we'll scratch yours and let's drive people to each other's sites. Let's tell each other's stories. And for us it was tell your brand story, tell your product story. And for our brand partners, we'd ask them, can you let people know that you like Huck Bearing to come check us out?\n\nCole Heilborn (50:48): I feel like everything we've been kind of talking about, and we talked about it in the beginning of the episode, is this just concept of loyalty and building audience loyalty, and all of these things we've discussed are kind of tactics and ways to do that. How do you measure that loyalty?", "token_estimate": 411, "speakers": ["Ben O'Meara", "Cole Heilborn"], "start_timestamp": "49:31", "end_timestamp": "50:48", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "bbc0bfb4-9333-4611-b2c7-f24047f72947", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 24, "content": "Ben O'Meara (51:04): It's a good question. I think we're getting a lot better at actually creating dashboards and tracking different KPIs around that. And I think the tip of the iceberg, not even the tip of the iceberg, but one is sales and repeat sales. What's the lifetime value of a customer? We are a retailer. That's how we pay our bills. Again, content and media is part of our DNA, but how often are you coming back to Huckberry and buying something? And that is loyalty. I think broadly the consistency of our open rights and click through on the Huckberry emails in our content, that's the very top of the funnel. You can't get as granular which customers necessarily did that, but you can look at those data points and understand if we consistently have the higher open rates and strong click-throughs and also time spent on page, whether it's a journal article or a video, I think that's a form of, or it's a touch point that gives you that data of is the customer gravitating to what you're putting out. (52:14): But absolutely, it does come back to the lifetime value of a customer, how many purchases they're making, how much time, how often they come back to Huckberry and interact with us. And then we track NPS scores. So you buy some what is an N-P-S-N-P-S, it's called Net Promoter, and it's sort of a directional survey that gets sent out. You've probably gotten them before with basically, how satisfied are you with this experience with this brand? And ours is consistently high. And so not only do we track the number, but it gives you a chance to write in what you liked, what you didn't like. And so we hear a lot of, Hey, I'm a long time customer. This is my third purchase, my fourth purchase. So we track that. We're constantly aggregating that information, our CX interactions, and we obviously know who the VIP customers are and know how many times you've bought from Huckberry and have those data points. So it's a combination of a lot of things. And then some of it is sort of the more anecdotal where it's people chiming in and sometimes it may be a single comment or a couple comments, but when you consistently see I love Huckberry on an Instagram post, or people resharing our content like Love Huckberry, this is awesome, another great article or love this collaboration. Those are all things that we track and pay attention to. So it's a variety of things that sort of give us that indication of customer loyalty and consistency to the brand.", "token_estimate": 620, "speakers": ["Ben O'Meara"], "start_timestamp": "51:04", "end_timestamp": "51:04", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "5dc240b5-4101-40b3-98a5-aaf3e595960f", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 25, "content": "Cole Heilborn (53:45): Yeah, man. Well, we're coming up against the end of our time for today, but I guess to kind of wrap it all up, what are you excited about moving forwards other than you're in a new space?\n\nBen O'Meara (53:57): In a new space? I think we were talking a little bit earlier, but I think what this new space actually the room that I am in, excuse me, represents one of the things that I personally am most excited about and the brand is very excited about it. It's one of our major strategic initiatives, if you will, for this year, is expanding our media and content and really rallying around video and bringing the brand to life in more 3D. So I'm sitting in our new video studio where we're going to be doing gear reviews and unbox scenes interviewing brand partners and founders, having musicians that are coming to town come in and not necessarily do a performance. Tiny Desk has got that, but let's talk about the gear that they need when they're on the road or their favorite dive bars in various cities. So excited for this studio to come to life. (54:45): And then we're going to continue to invest in video externally, like going out on adventures and making sure that we're capturing inspiring people in places and again, bringing these stories that we've been telling for so long to life and new mediums. So I think it's just going to be a great way to better connect to product, brand story and people. So I'm very excited. We're particularly bullish around video and eventually podcasts. I'm going to be calling you up and picking your brain, but again, we're just, as I've said many times before, and I don't mean to sound like a broken record or cliche, but we're just so fortunate to be surrounded by such incredible stories. And again, that's everything from we nerd out on products. We are gearhead, and so the stories of a product, the story of a brand to the story of someone who is an entrepreneur or an adventurer, and how do we tell those stories in more interesting ways and get it in front of more people? So very excited about that. Broadly,", "token_estimate": 522, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "53:45", "end_timestamp": "53:57", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "5dbfe5f8-d00a-4737-be29-b94f2df86ea6", "episode_id": "cf1c80e6-6951-4068-afbc-059127cd6805", "cms_item_id": "68225dfc7bb476527f8c486f", "chunk_index": 26, "content": "Cole Heilborn (55:44): If folks want to follow along with either you personally or any of the platforms with the brand, where can they go to connect?\n\nBen O'Meara (55:51): Definitely, I mean, hura.com got to start with that hybrid.com, and obviously we're on all of the social media platforms. Instagram, I'm on LinkedIn, I'm on social media, so just look up my name. Always love to connect and hear from people, connect with other creatives and business owners and customers.\n\nCole Heilborn (56:08): And if you want to hear an interview where Ben interviews Matthew McConaughey, that's also on the internet, so I'll just throw that out there.\n\nBen O'Meara (56:16): Thank you for that plug. Yeah, our new Austin neighbor. Yeah, it's on the Huckberry Journal. It's also on YouTube. But yes, that was quite the experience.\n\nCole Heilborn (56:27): I bet. Well, Ben, thank you for taking the time today and I hope you have a great rest of your day and looking forward to well, seeing the next email in my inbox.\n\nBen O'Meara (56:35): Yeah, cool. This was awesome. Thanks for having me.\n\nCole Heilborn (56:37): Yeah, no problem. Take care. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 337, "speakers": ["Cole Heilborn", "Ben O'Meara"], "start_timestamp": "55:44", "end_timestamp": "56:37", "podcast_index": 72, "episode_name": "EP 72: Ben O'Meara | Foundations of Huckberry | Huckberry", "slug": "ep-72-ben-omeara-foundations-of-huckberry-huckberry", "web_url": "https://www.portsidepro.com/podcast-feed/ep-72-ben-omeara-foundations-of-huckberry-huckberry", "guest_name": "Ben O'Meara", "guest_title": "VP of Marketing, Huckberry", "categories": [], "short_description": "Curated Product, Storytelling, Email", "podcast_length": "44:94"}, {"id": "a04c90dd-2186-471d-97ab-7e4067a8d30b", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 0, "content": "Emily Holland (00:00:01): I want to start a podcast. Okay. Why? And the reason being is because, like you said, anyone can start a podcast, which is awesome, right? You really just need your phone. You need a computer, and you need a platform to be able to distribute it. Like those three things, you can start a podcast, however, it's very time consuming and there's a lot of BS as you know that goes into it. If you're not excited about editing and you're choosing to edit your podcast, that's going to seem like a slog, and I'm speaking from experience on that. I absolutely hate editing.\n\nCole Heilborn (00:00:33): Welcome to the Backcountry Marketing podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Heur, and today I'm sitting down with Emily Holland. She is the host and producer of the Nature Untold Podcast. She was the former co-host of the Stoke Cast and now she runs a freelance podcast agency. How are you doing?\n\nEmily Holland (00:01:20): I'm doing great. Thanks for having me, Cole.\n\nCole Heilborn (00:01:23): So good to be here for a number of different reasons. Yeah, how's your day Going?\n\nEmily Holland (00:01:29): Well, recently, as you said, freelance podcast consultants, so figuring out what that looks like on a day-to-day basis, and it's been pretty exciting, so I'm excited about it.", "token_estimate": 465, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:00:01", "end_timestamp": "00:01:29", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "979b7915-3d8c-4815-b6ea-f3432f19b7f7", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 1, "content": "Cole Heilborn (00:01:41): Well, yeah, I'm excited to dive into that. I'm excited to dive into, I think really just our entire topic today. It's ironic we have yet to have had a podcast focused guest on the podcast, so this is kind of groundbreaking. I don't know about you, but I feel like the world of podcasting is kind of like the Wild West. It's very new, it's very confusing. There's lots of opportunities, but there's, there's really no one way to do it. And so what I hope we can do in our time today is just dive into the world of podcasting, and I'd love for you to share your experiences and hopefully we can go over some common questions. I think you get asked a lot about what is this world of podcasting that folks are currently listening to. Alright, so if you could first give us a quick introduction on yourself and what outdoor activity are you currently enjoying the most?\n\nEmily Holland (00:02:36): Yeah, so introduction for myself. My name is Emily Helen. My pronouns are she and her, and I'm most importantly probably my life, a dog mom. And then secondarily, I try to make money doing things. So I love podcasts. I call myself a podcast nerd that doesn't even really begin to scratch the surface on my love of podcasts. I love creating podcasts. I love helping other people create podcasts, and I love listening to podcasts. So all the things love it. And the outdoor activity that is most exciting to me right now is I think trail running because I go through waves of really loving trail running and then doing it too much and then hating it for a couple months and then loving it again. And now that we're going into fall season and I gave it a little bit of a rest for a week or two, I'm back stoked on it, and I just want to do it every day.\n\nCole Heilborn (00:03:34): And I got to imagine being out on the trails is probably a nice therapeutic spot for you as you're spending most of your time dealing with podcasts in the day to day.", "token_estimate": 491, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:01:41", "end_timestamp": "00:03:34", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "c1d9de35-c667-4881-ace8-a0a2638bc60a", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 2, "content": "Emily Holland (00:03:44): Yes, it's good to get away, but I have to say, I also, a lot of people are purists with running and they don't listen to anything, and I absolutely listen to stuff. I listen to podcasts on the way up to distract myself and then generally emo punk on the way down to get myself going.\n\nCole Heilborn (00:04:06): So yeah, walk us through a little bit of your history with the few different podcasts that you've been involved with up to this point.\n\nEmily Holland (00:04:15): And I think it was in 2017, I met my former co-host, Jonathan Rono, who is running, was running Explorer inspired, and that was an outdoor media outlet at the time, it was a blog, it's still running now. And we met in the climbing gym in Boston and we started talking, and I was starting to write a little bit about my experiences going into the outdoors. I wasn't a professional writer or anything, I was just trying to share my experiences. And we talked a lot. And I ended up going to Outdoor Retailer with him, and we were sitting outside of a brewery somewhere in Denver, and we were like, you know what? It would be awesome if we could just start a podcast basically, almost selfishly, so we could ask the people that we want to talk to us and tell us about their journeys and their lives. (00:05:08): So we did that. I mean, we got excited about the idea and we were like, what form will it take? Who do we want to have on? Who is our hit list? And then we started it, and that was the Stoke cast. And so we split up pretty evenly responsibilities between hosting and producing and outsourced editing on that one. And we just did long form interviews with awesome people in the outdoor space. There could be entrepreneurs, there could be athletes, there could be activists, artists, all kinds of different folks. And it was one of still the privileges of my life to be able to speak to these people who I looked up to so much and learn so much from them. And also about, quite honestly, myself in the process, because interviewing people is a great way to learn about yourself as well. So that was my start in Stoke Cast, and then in February of 2020, I stopped drinking and I was looking for something that had concentrated stories about people in the outdoor space who were struggling with sobriety or recovery or addiction, and I didn't really find anything. (00:06:20): There's definitely episodes of certain podcasts out there that have those stories on there for sure, but there wasn't a place where those people were coming together on a consistent basis. And so I thought about it a lot and I sourced some ideas from other folks or really asked people, would this be valuable to you, which we can talk about, because I think that's a super important part of starting a podcast. And people said yes, and I started to think about what that would look like and what I would want to represent as far as the interviews go. And then the Nature Unfold podcast was started, pre-production was started in August of last year, and then January I actually released the first season of the Nature Unfold podcast, and now we're nearing the second season end.", "token_estimate": 790, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:03:44", "end_timestamp": "00:04:15", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "c321d47b-3c05-4bfa-8e6a-26d68192fb63", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 3, "content": "Cole Heilborn (00:07:11): That's awesome. And you've got 21 episodes published to date, is that right?\n\nEmily Holland (00:07:15): 21, yeah, 21 today actually. So great count.\n\nCole Heilborn (00:07:20): I was looking at Apple Podcasts just before we jumped on this call. And how many did you guys publish with the Stoke Cast? That was a lot.\n\nEmily Holland (00:07:27): Yeah, for the first year at least, we did once every week, and we both had full-time jobs outside of doing that, and that ended up being a big time commitment. And so I think I definitely got to a hundred before I left the Stoke cast with Jonathan. So that certainly, yeah, that was a big amount for us. A lot of podcasts, I would say, I think it's 5% make it past 20 episodes, something crazy like that where it's like you see a lot of stuff out there on the internet that's like three episodes, and then they figured out, oh, this is actually a lot more time consuming than I thought it was going to be. I don't want to do it anymore.\n\nCole Heilborn (00:08:13): I understand that. I can relate. So I want to go a little bit back to kind of set some foundation as we move forwards. I'm curious to hear, do you know where the origins of podcasting came from? Because I just remember it kind of appearing one day. I feel like when Apple, what I remember is Apple launched some sort of podcasting format, and for a long time, probably for the last 10 years, I've always been sort of confused as to what a podcast actually was.", "token_estimate": 373, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:07:11", "end_timestamp": "00:08:13", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "4d224748-f3f9-447d-8579-30c22e666673", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 4, "content": "Emily Holland (00:08:44): Yeah, I mean, it's a weird space. I dunno the actual origins. I think the first memory I have though of listening to a podcast is listening to all Things Considered from NPR. And the reason I listened to that is because one of my sister's most intelligent friends was like, I was listening to this podcast called All Things Considered, this is like 2014, I want to say something along those lines. And I as well was very confused about what that purple app was on my phone that kept showing up that I was like, why can't I delete this? And now here we are, but I mean, it's an incredible space and I think definitely the last five years has expanded exponentially, but the last two years in which people were in their house, they had extra time. They also were realizing for the first time in a long time, for a lot of people, what they actually were interested in, they're like, I don't want to do this X job. (00:09:44): I want to do this other thing. And part of that is podcasting. And so in the last, I think 90 days, 600,000 podcasts have been created. And so there is an incredible amount of content out there. And like I said, not all of those will go on to become the Joe Rogans or the Dak Shepherds of the world, but that's the amount of creation that we're seeing right now, and it's incredible. I'm so happy that that's happening because there's so many people out there that should have a podcast and that are interesting and have great perspectives or have great journalistic backgrounds, and they should be storytelling. I get excited about the exponential growth of the podcast space,\n\nCole Heilborn (00:10:28): But what about the podcast format makes it so interesting to listen to? Because in most forms of digital communication, shorter is better, but that seems to be the opposite in the podcast world.", "token_estimate": 462, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:08:44", "end_timestamp": "00:10:28", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "e76d6ab6-9d2e-4707-8adc-c3a0831c36a7", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 5, "content": "Emily Holland (00:10:39): I know, it's amazing. There's podcasts that are like five hours long and people listen to them. I'm just like, wow, that's incredible. I mean, I guess you could say the same thing for audiobooks too, right? The popularity of those as well. But for podcast itself, it feels like you're listening in or part of an intimate conversation and with interesting people who you would never be able to speak to in normal life for the big ones in the world, for our outdoor space, certainly if you went up to an Emily Harrington or someone who's an outdoor athlete who has a big name, she wouldn't be mad that you went up to her, not like a regular celebrity. But in general, we're listening to these intimate conversations that are so interesting, are so engaging, funny. Sometimes I cry listening to podcasts. So I mean, there's no other medium that you can go about your day and take in the same time and go away with a lot of value. (00:11:41): So that's part of it, I think. Yeah, and then the convenience factor, I mean, I have to sit down and watch YouTube. I have to watch Netflix, I have to watch all these streaming services. I can take a podcast with me anywhere, and now that we can also download them offline, we can literally take them into the back country with us as well. So that mobility of the audio format as well is so incredibly awesome for us. And I think even more for people who go into the outdoors, the folks in this outdoor industry is like, we spend hours and hours and hours doing hard things in the mountains, and I don't know a lot of people who don't listen to anything while they're out there for hours. I mean, that's pretty incredible if they are. So that I think is a unique part of the outdoor industry where quite honestly, outdoor brands I don't think have tapped into nearly enough of the podcast space to date, and it's a big opportunity, I think, for brands to do.", "token_estimate": 481, "speakers": ["Emily Holland"], "start_timestamp": "00:10:39", "end_timestamp": "00:10:39", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "1d77dd61-10b0-4816-aefe-5dd846094016", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 6, "content": "Cole Heilborn (00:12:45): Does the success of podcasting being that the format is so inviting, and as you said really you're being invited into this intimate conversation with two people or a person who you might not otherwise have a chance to listen into, does that say something about the state of consumers, our audiences, or just society as a whole?\n\nEmily Holland (00:13:07): Yeah, absolutely. I mean, I think last year showed us that connection is crucial to our wellbeing. I mean, I don't know about you, but last year was really hard mentally for me to be away from the people that I want to be around, or even the interactions of meeting someone new. We all had our little pods in which we were able to see all the people we already know and knew their backgrounds and knew who they are, but meeting someone new, interesting at a friend's party that you're going to, or a wedding that you happen to go to, those types of interactions, whether you're extroverted or introverted, they're really life-giving. And so to have those available to you in your pocket at all times, that was a godsend to me for the entire quarantine and now beyond of course, too.\n\nCole Heilborn (00:14:03): Yeah, well said. So transitioning gears a little bit, you've recently started your consulting business. As we were chatting earlier, you mentioned that a lot of people are interested in creating a podcast, but they have no idea where to start. Let's start at the very beginning. Why would someone want to create a podcast? How do you work through this process with folks?", "token_estimate": 391, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:12:45", "end_timestamp": "00:14:03", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "8f605292-3790-45e2-a1ee-bc811ef9f291", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 7, "content": "Emily Holland (00:14:24): Yeah. Well, it's interesting that you phrase it that way because that's the exact question that I would ask someone if they came and said, I want to start a podcast. Okay, why? And the reason being is because like you said, anyone can start a podcast, which is awesome. You really just need your phone. You need a computer, and you need a platform to be able to distribute it. Those three things, you can start a podcast, however, it's very time consuming and there's a lot of BS as you know that goes into it. If you're not excited about editing and you're choosing to edit your podcast, that's going to seem like a slog. And I'm speaking from experience on that. I absolutely hate editing. So those types of things, all that admin stuff, that's going to feel really hard if you don't have a solid reason why you started your podcast in the first place. (00:15:18): So you got to have that solid why. The other thing is how are you going to dictate your success of this podcast? Because there's huge podcast companies that have millions of dollars that they're putting behind huge podcasts with big names and celebrities and all this stuff. If your success is deemed on you being in the Top 10 podcast with, I hate to keep going back to Joe Rogan, but he's just the greatest example of podcast success. If that's your success metric, again, it's going to be really hard to get there when you're just an individual creator. So understanding what success looks like for you, and that might be more intangible, that might not mean that you're going to hit 5,000 listens per episode. It may mean that one person reaches out to you and says, this conversation made me feel like I was seen or heard today, and that's your success metric. Sure, you can have numbers and all this other stuff, but you need to bring it back to the reason you wanted to start it in the first place when you think about success metrics. So I think those two are really, really important to think about when you start your podcast.", "token_estimate": 508, "speakers": ["Emily Holland"], "start_timestamp": "00:14:24", "end_timestamp": "00:14:24", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "f8d66eae-84ff-4e56-8a65-ab3e3cf41773", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 8, "content": "Cole Heilborn (00:16:34): So really digging and uncovering that why for you as a producer or a host, so essentially that's what keeps you going when you're trying to pass that 20th episode.\n\nEmily Holland (00:16:45): Yeah, it's your mission statement, it's your vision. What do you have in your mind when you think about it? When I think about starting the SoCast, I think we could have done a better job probably of creating a vision for ourselves. We really wanted to talk to really influential people, and we loved having those conversations, and it was awesome and people got value from it. But looking back, I'm like, I wish that we had more of a why that we established up front, because there were times where it was a slog because we had to put so much work into it, and we didn't have that agreed upon why. So that's why I go back to that too, because I didn't do that the first time, and I think that would've made some of the moments easier when I was so frustrated by guests not answering or potential people not showing up for their interviews or all this stuff that can happen while you're a podcast host.\n\nCole Heilborn (00:17:43): Is that different with the Nature Untold podcast? Do you feel like you have a stronger why?", "token_estimate": 310, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:16:34", "end_timestamp": "00:17:43", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "a03d992f-4bf7-4cd2-b1b3-761a2ba9f592", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 9, "content": "Emily Holland (00:17:47): Yeah, I think I was sober myself. I wanted to hear this stuff. And then the other piece of that was I went out and I asked groups, will this be valuable to you? It will be valuable to these people. This is how I'm feeling about my sobriety. This is what I don't see in the media landscape. So this is my why. The reason I do the Nature Untold podcast is because I want to have better representations of sobriety and addiction and recovery in the outdoor space, not just all the doom and gloom, although that can be part of people's stories, but also that you can have joy and fulfilled lives after you become sober. And we don't often see that in media. So I come back to that all the time because I'm like, why am I doing this? Why am I doing this? When I'm looking at Adobe audition and editing stupid thing, I'm like, why am I doing this? And I come back to, because this is, I'm providing a service basically to the community, and it feels really good to provide that service and to feel like you're making just an inkling of a difference in someone's life. So I can go on and on about that podcast, but I do feel like I set up well there. And then my success metrics were just that. I said, if one person reaches out to me and says, you helped me with my own recovery in some way, cool. That's a successful podcast in my opinion.\n\nCole Heilborn (00:19:20): And you mentioned that you went out, you said groups and said, would this be helpful? Who were you chatting with? Were those brands or were those individuals?", "token_estimate": 387, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:17:47", "end_timestamp": "00:19:20", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "f1643189-63e2-426e-9519-694a123008f1", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 10, "content": "Emily Holland (00:19:29): Yeah, so there's the great group on Facebook, Basecamp where I would put a call out and was like, I'm thinking of doing this. I'm looking to talk to people about it, and kind of sourcing out the idea. And then I had 30 minute conversations with 20 different people to see what they would find helpful. Some of those people ended up being on the show themselves, and some of those people just ended up being great resources for me to ask questions to and to see what they thought about the concept. There's great Facebook groups out there specifically. There's a couple for Colorado that are sober Coloradans or Alcohol Free Outdoor Women is one, I think. So just reaching out to groups like that and posting in there and saying, Hey, I'm thinking about doing this. Will this be valuable to you? And then not only were people like yes, but then following up with those people and asking for their time and understanding what would be valuable to you, what stories do you want to hear? And I think that that is not only relevant for individuals who are thinking about starting podcasts, but brands too. When you're thinking about creating your own podcast, how can you make sure that you're serving the customers you already have and then potential customers as well? Because obviously starting a podcast is about brand recognition and brand resonance as well.\n\nCole Heilborn (00:20:53): And I want to jump back to that in a moment, but considering a format, there's tons of ways you could do it. You could have a host, you could have a host and a guest, you could have. What I've really started to enjoy and have been actually looking out is podcasts that have amazing production quality, and they're almost like they're giving you an audio experience, and it's so much deeper than just people talking. How do you decide what are things people can consider in terms of a format?", "token_estimate": 476, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:19:29", "end_timestamp": "00:20:53", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "2daba04f-5e0f-4e1d-99c9-2fa1603f8457", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 11, "content": "Emily Holland (00:21:27): Yeah, that's such a good question, and I think it really comes back down to how much time do you have to give to this and what are you outsourcing and what are you doing yourself? If you're a lay person that has no idea how to use editing software, and you're going to have to learn all of that in order to be able to produce your podcast, I don't know if a narrative, storytelling, audio experience would be the right fit for you to start off with. If you are really yourself, you know how to produce something. And so if you already have those skills or you were a radio journalist before or whatever, you know how to piece together a story, then great. And maybe that format is what feels comfortable to you right now, and you can do other formats in the future, but you start with what, for me, I didn't have any background in doing anything. (00:22:21): And so for the SoCast, we were like long form interviews, that's what we like to listen to, so let's do that. And I think also in a long form interview, there's sort of this unraveling of the guests, and you can start to really get to know them in this really deep way, especially when it's not cut throughout the entire process. And for the Nature Untold podcast, I was going out on my own doing this thing for the first time, handling everything. And so what I decided to do is I'm going to stick with what I know, which is long form interviews for the time being. That being said, in this season, the next episode that's coming out will be more of a cut narrative conversation, hopefully audio experience. So I think it really is like, okay, what's your skillset? What do you already know how to do and what are you willing to learn how to do? So think of that in time spent, money spent, and then also what do you like to listen to? And then finally, what's going to make you most comfortable upfront? You can always change it down the road. You can always have different formats if you want to and play with different things, but I think those are the three areas that you should focus on in thinking about what format you'd want for your podcast.", "token_estimate": 535, "speakers": ["Emily Holland"], "start_timestamp": "00:21:27", "end_timestamp": "00:21:27", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "49971258-da03-4f3e-9de1-a929d58f9bd3", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 12, "content": "Cole Heilborn (00:23:39): Yeah, editing man, is it great, but it can get real tiring, really quick,\n\nEmily Holland (00:23:49): Drank water, as you were saying that I absolutely hate editing, and I know I've mentioned that four times already, but I think it's just also how does your brain work? Does your brain more theoretical things? Do you like to think about story and do you like to just really be in the moment with the interview or does your brain to figure out how everything fits together? And in all these different ways in which you can use the software to create, again, this audio experience. That's a decision you have to make, and I understand why someone would not want to edit, but I also understand why someone would want full control over that as well. So again, all things that just do a little internal digging for yourself, and then you can make decisions to start with, and nothing is set in stone. You can always change it later on.\n\nCole Heilborn (00:24:46): So we've kind of been discussing the solo creator and their journey. I want to transition a little bit, but before we do that, what are the biggest challenges that the solo creator faces? I think we've discussed a few of them, but other than time and just the ability to keep going, what are the things that get in the way?", "token_estimate": 327, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:23:39", "end_timestamp": "00:24:46", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "ea5308d4-e7cd-4a12-8890-57a2556f9dd6", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 13, "content": "Emily Holland (00:25:08): Yeah, I think the things that get in the way is that there is not one platform that you're using for everything you need to do to be a podcast creator. And I'm hoping that something like this will come out soon, but if you're thinking about monetization, you'll probably want to have a Patreon. For folks who aren't familiar with that, it's basically, it's like a tip jar for creatives. You can give them a monthly subscription of $1 or $3, and usually you get stickers or exclusive stuff out of that. So then you have to manage a Patreon. Then if you're promoting your podcast yourself, meaning you're creating all the graphics and all the images for it, okay, you might have to have a Canva membership For those who don't know about Canva, Canva is an awesome format or platform rather that is pretty inexpensive, and you get to create beautiful graphics for anything that you're doing. (00:26:06): You can use that for proposals, you can use it for Facebook graphics, Instagram graphics, whatever. Okay. So then you have Patreon, Canva, then you'll have a distribution platform. So wherever you're either hosting your podcast itself or something like Anchor that's owned by Spotify where you upload your podcast to it and you distribute it through there, and then I'll have all your stats in it. Okay. That's just three things. And then not even to mention all the social media management of doing all that, and then also if you have a website. So I think that is a big part. It's like you're creating content, but then there's all these peripheral things that are around that content that need to be managed as well. It's not really enough to just produce a podcast. You have to promote the podcast, and how do you do that? You do it with great graphics and images and copy and that kind of stuff. (00:27:00): Then how do you make money off of it? Well, Patreon's a great access for that. I know we already talked about time spent, but it's also where you're spending your mental energy throughout the day too. It's like content creation and promoting is a different part of your brain than interviewing a guest and editing the show, all of this stuff. So all to say, there's a lot of different pieces that go into it. If you're not trying to monetize it, it's not as heavy of a lift. However, you still need to promote it if you want people to hear your podcast. So I think that's the biggest challenge is that individual creators and brands alike, I mean, there's just these huge studios that have so much money to manage all the stuff that you really can't compete on that realm. So just knowing that having a podcast means managing all these different parts of having a podcast,", "token_estimate": 678, "speakers": ["Emily Holland"], "start_timestamp": "00:25:08", "end_timestamp": "00:25:08", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "f049ed62-35bb-4c09-868f-71bb5876c99d", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 14, "content": "Cole Heilborn (00:27:56): Man, you just opened up a whole nother can of worms.\n\nEmily Holland (00:28:00): I think we're going to start a business, I think.\n\nCole Heilborn (00:28:02): Well, that's what you have done.\n\nEmily Holland (00:28:04): That's right. Yeah. Yeah. I mean, that's the thing is this is the stuff that I think is really exciting and also can be really intimidating for folks, right? It's like I just rattle off a bunch of stuff that I personally use. You don't have to use all of that, but I think when you think about all that stuff, it can seem daunting to start your own podcast. However, we live in this incredible time in which you have an opportunity to communicate either your own story or stories around your community through this beautiful medium. And I just think that more people should be doing it. I know there's tons of people who have started over the past two years, and that's awesome, but I think even more can, and I know that there's some folks out there that really want to, and they're a little scared to start or they don't know where to start. And I think that's what gets me fired up is helping people who want to share stories and want to communicate something to their communities and they just don't really know where to go, or they feel stagnated and they've done what they could, they they're at a point now where they need some shaking loose\n\nCole Heilborn (00:29:15): From the monetization perspective, how do you start to consider how to do that?", "token_estimate": 375, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:27:56", "end_timestamp": "00:29:15", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "6b9c1876-f972-4518-83c5-8d12f933b3bf", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 15, "content": "Emily Holland (00:29:20): Yeah, so that's another thing that I usually tell people when I first start either working with them or they just come to me and ask for answers to questions. So you have why you have your success metrics that you're thinking about, but it's important too to think about even before you about monetization, before all of that, what do you want your listeners to walk away with from your show? So three to five things that you want them to walk away with. You have your vision, your mission we already talked about. Then also, who is your target audience? Who are those people? Write that down. Who do you want to target? Why do you want to target those people? And then based on all that information that you've sort of dim some internal digging around, who would be the ideal brands that you would work with to create partnerships with around the podcast? (00:30:15): And partnerships can mean a lot of different things, so we can talk about that as well. But I think before we even start to think about pitching brands or starting a Patreon or whatever you're thinking about doing, you got to get that stuff dialed. And then that'll also make it super easy to create a pitch deck, why, what the takeaways are, who your people are and who you want to work with and why. So I think that's just what I want to say before we tap into monetization. Now, monetization is pretty amalgamous. It can be literally anything. So there's so many different ways to monetize a podcast. Now, if it's a brand, they may not want or need to monetize their podcast because if they get three customers from one show, cool, that pays for basically the monetization part of that. It's the top of their funnel or whatever. (00:31:07): So for an individual though, and this brands can do this as well, you can do a couple different things. So there's specific brand sponsorships. So this is pitching brands who you want to work with on advertising on your particular show. Some people do per episode, some people do per season, some people do per month. So it depends on how many episodes you have per month. It depends on how you want to structure your pricing. It is the wild West still, so it doesn't need to be hard and cut and dry. So that's the first one is brand sponsorships, and we can get midtier or grittier if you want. Then the next one, which I don't personally have experience with, but I know people do use this, it's dynamic or static ad insertions. So usually in your distribution platform, something like Anchor or whatever you use to distribute your podcast, there's an option to add ads into that. So people who, or companies rather that want to get more advertisements out there, they'll create a partnership or work with something like Anchor and they'll say, Hey, we want to advertise on X number of podcasts per month. So they basically connect you with those ads and they put them in your podcast themselves.", "token_estimate": 735, "speakers": ["Emily Holland"], "start_timestamp": "00:29:20", "end_timestamp": "00:29:20", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "8e70df84-22d9-4a59-98f6-c45c47d4cd25", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 16, "content": "Cole Heilborn (00:32:31): And this is the bumper at the beginning of the episode or in the middle\n\nEmily Holland (00:32:34): Pre-roll is what that's called. Exactly. And that can be good and bad. You can make money off of that for sure. However, it can be a little bit off putting if the first thing that you're hearing is a Geico commercial. So if you want full control over the voice that your podcast is creating, brand sponsorship might be a little bit better. There are ways that you can read ads as well. And you can work with a company like Advertise Cast, where they connect you with, again, advertisers, but you can read the ad yourself. You don't have to have it be like an insertion from the company itself. So there's that option. Then there are affiliate deals. So maybe you're not at a place yet where you have enough listenership to warrant add sponsors for every single show, but you say, okay, Patagonia, let's do an affiliate deal. I don't think they would ever do this, but here's an affiliate deal. So what we'll do is we'll have a code, and anytime someone uses this code, we get 10% of the purchase that they made, and the customer, the listener gets 20% off or whatever. And so you can cut a deal like that as well. And that depends how many people actually utilize the code, obviously, but that's a little bit more money coming in your pocket. (00:34:02): And then the last thing I'll say about monetization is crowdfunding we talked about, so it's Patreon Anchor has an opportunity to do this as well. They actually just announced today, I believe that you can have folks sponsor a particular show, so a new platform to do that on a consistent basis. And I don't think they will have tiers. Patreon has the offerings that Patreon has, but that's a new offering from Anchor, which again is owned by Spotify. So there are these little ways in which people that what you're doing can promote and support you. So they can do that through Patreon. They can literally send you a Venmo, you can ask people to send you a Venmo or give you a cup of coffee if they like what you're doing. So those are sort of the main four buckets that I would say. And then the last thing I keep saying, the last thing I'll mention, but there's another piece of this, which is I usually, I do use Amazon affiliate links as well. So anything in my show notes, that's like a book, a movie, anything like that, I do use some sort of affiliate link. It's not always from Amazon, but there's tons of sites out there that have affiliate links or just random companies in the outdoors that will do an affiliate deal for you if you're doing a newsletter and mentioning them around your podcast. So there's all these little ways, it's just a matter of getting them all together to create a good chunk of money. And that I think is a big, it's a time management thing.", "token_estimate": 715, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:32:31", "end_timestamp": "00:32:34", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "9e68fdd6-3fec-4581-b507-e26ef4b3bc0d", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 17, "content": "Cole Heilborn (00:35:45): All of those sound great, but what is required of the podcast in order to make any of those viable?\n\nEmily Holland (00:35:52): Such a good question.\n\nCole Heilborn (00:35:54): Is it a download? Is it a listener thing? How does that work?\n\nEmily Holland (00:35:57): Yeah, so for the Patreon and that kind of stuff, I mean, you can do that whenever, if anyone listens to your show, you can be like, here's my Patreon, go give me money for dynamic ad insertions. It depends on the distribution platform. So for Anchor, there is no minimum for an amount of listens per episode for you to start doing that. You can start doing that from day one. Again, that's not really in control in your controls, who it is, and you can control who it is. You can decline if you don't want to support a tobacco company or something. And then the other thing is that with brand sponsorships, this is still Wild West, we talked about, however, the general format, if you will, of brand sponsorships for bigger shows are cost per mill, CPM. That's the acronym. And so basically what that means is that there's a particular dollar amount per mill that you should be charging for advertisements. And there's one that's\n\nCole Heilborn (00:37:13): Mill as in million\n\nEmily Holland (00:37:13): As in, sorry, mill as in a thousand. So cost per a thousand. Yeah, mill would be, oh my God, I think it's the not Italian Latin word for a thousand or something. I don't\n\nCole Heilborn (00:37:28): Dunno. I was going to say, how many podcasts actually reach a million?", "token_estimate": 391, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:35:45", "end_timestamp": "00:37:28", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "c598b4b3-a0d7-46ca-9e22-43c770ac4404", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 18, "content": "Emily Holland (00:37:31): Oh, God, I can't. I would love if there was a transparent place that you could see everyone's podcast stuff, but I hope that doesn't actually happen. Yeah. Anyways, so for CPM, this is really getting nitty gritty, so I'll just try to be as concise as possible. Basically it means that there's a general market rate for an ad, either a 32nd ad or a 62nd ad. So that's what CPM does is it gives a market rate. The current market rate, if you have 10,000 listeners to an episode of each of your show for 32nd ad is $150. And the 62nd ad for that same amount, 10,000 is $250. Now, that's market rate. Sure. But we talked about all the other things that go on outside of just people listening to your podcast. They're connecting with you on socials, which sometimes have huge followers as well. They connect with you on Patreon, they might connect with you in an actual person as well. (00:38:38): So there's all these other value adds that come with being a podcast that I think add more financial value to an ad as well. So you can build deals that maybe are not just CPM, it could be here's the cost for the ad, and then we're going to throw in an affiliate link, and we're also going to throw in a social media mention and a giveaway. So you can get in front of our Patreon, which is our most loyal listeners every month. Cool. That should cost them more money than just the CPM rate. So that's what I think about when I think about creating your own brand sponsorships is like, let's create a partnership that you can work with this brand for a long time and that everyone is succeeding from. So getting them in front of more engaged followers, not just in front of the podcast listeners who listen to the podcast and then they throw their phone, who is on the social, who's on the Patreon? These are the people that you want to be targeting. And so those types of pieces of your podcast world that you're creating are incredibly valuable and you shouldn't undersell them when you're asking for sponsorship dollars.\n\nCole Heilborn (00:39:53): Coming back to Joe Rogan, the whole Spotify deal, that was like, what? I don't remember, 50 million, 80 million.", "token_estimate": 546, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:37:31", "end_timestamp": "00:39:53", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "a559b312-249f-4edc-936d-6cac83456791", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 19, "content": "Emily Holland (00:40:00): It was a hundred million dollars that they paid him to be exclusively on Spotify.\n\nCole Heilborn (00:40:05): Okay, so I'm going to do a really drastic comparison here, but that deal compared to 10,000 followers for 150 bucks,\n\nEmily Holland (00:40:16): Oh man, yeah,\n\nCole Heilborn (00:40:19): That 150, I realize everything you just said, there's a giant asterisk next to that 150, but that still seems extremely low for maybe the amount of reach and engagement that hopefully a podcast has.\n\nEmily Holland (00:40:36): And I think it is too. I think you're asking if a brand asks you to do CPM pricing, you're basically asking the person to diminish their trust that they've had with their listener, especially if it's a brand that just reaches out to you and says, I want to sponsor this show. Here's what I want to do. So I think, yeah, I think it's all about how do we create a more strategic partnership. I don't want to work with you for a month. I want to work with you for a year, and then we can decide where our partnership is there. I think 150 is super low. I personally would not add an ad for 30 seconds with my audience who is, it's pretty thoughtful and intentional show. I don't want to add a 32nd ad unless I actually think it's adding value, and I think it's priced right. (00:41:31): So yeah, I think that's why I don't think you need to lead with CPM If you're a person who's reaching out to brands and asking for sponsorship. Not all brands know about CPM and they might now, but they also don't need to operate in that way. There's no legally binding thing that says if we advertise, we have to go off of CPM. There's nothing that says that. So you can create the kind of deals that you want to create based on how much you think your worth and your time is worth that you're putting into your podcast and how much you want to partner with that brand on a consistent basis.", "token_estimate": 481, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:40:00", "end_timestamp": "00:40:36", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "10aefa59-3fd8-479c-8309-790681fca2f6", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 20, "content": "Cole Heilborn (00:42:11): Well, you made an important point there. It's like how much are you willing to open up the level of trust that you've built with your audience to a foreigner, and hopefully this foreigner embodies the same values that you do and fits well, but that still is, I mean, the podcast is an intimate experience, and as soon as you start to open that up to outside voices that could get really muddy and not sit well with an audience.\n\nEmily Holland (00:42:41): Yeah, definitely. And you can tell when it's happening, when you listen to a podcast and you're like, God damn it, this ad read really, this is what they're talking about,\n\nCole Heilborn (00:42:49): Or when it has literally nothing to do with the hosts. I listen to a podcast and it's two men and they're reading about some women's product, and I'm like, you guys, why?", "token_estimate": 213, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:42:11", "end_timestamp": "00:42:49", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "e344a1d2-494a-4673-948b-97d73b28c041", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 21, "content": "Emily Holland (00:43:00): I know. I know. They're in love. Probably the bras that they do a lot of of big podcast promotion. Yeah, I mean, I totally agree. I think that that's why something like Patreon is awesome because it's totally just about the community supporting someone doing a rad thing. That's all it is. Yeah, I think that if you're ad reads are not congruent with what you're trying to get across in your podcast, yikes, that feels off to me, especially as we move forward, not just in the podcast space, but as a society of being more story focused, being caring more about the thought behind something versus just throwing something together and trying to make money in a very almost sleazy way. It feels a little slick to me. There's great examples of people who do add reads. Well, Chris Callous on a normal cast as an amazing job of making his ad read super funny and engaging, and they're like their own audio experience in themselves. (00:44:10): There's still four products that have to do with climbing. It's a climbing podcast, but they make me want to buy from Black Diamond. I'll just say that. He does a great job of that. The other person who does a good job of it is not to just use climbing podcasts, but for the love of climbing, Kathy Carlo, she does a great job of doing ad reads that are funny and thoughtful and sometimes really cute. So she does a great job of those. So I just say that because those are two great examples of people who have created good brand sponsorships, longstanding brand sponsorships, and they're still having fun with ad reads and making it super engaging. So it's definitely possible. It doesn't need to be a droning on and on about which bra size is going to fit you best. Cole is red.\n\nCole Heilborn (00:45:03): I don't have a whole lot of experience there. I would turn down that advertisement request if that was asked of me.\n\nEmily Holland (00:45:11): Yeah, yeah. Cool. Good to know.", "token_estimate": 488, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:43:00", "end_timestamp": "00:45:11", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "c3b55674-0e36-4931-8679-8a5daffaf085", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 22, "content": "Cole Heilborn (00:45:14): But I think what's also interesting is that the monetization of a podcast, it could be so far from anything financial. There are so many other values that you started to alluded to that you can never make a dollar or put a dollar in your wallet, but you get so much else out of it and so many other different ways.\n\nEmily Holland (00:45:37): Yeah, absolutely. So there's a couple of different things I would speak to there. The first of which is if you already have other products, let's say, whether they be services or digital courses or events that you're hosting or even physical products like apparel, having a podcast and gaining people's trust and having authentic relationships with people who are listening to the podcast, that's a great way to build trust with them and then to build authenticity and then who we buy from people that we trust and we think are authentic. So I mean, it's not in a sleazy way. It's like you're still doing it in a way that has integrity behind it, but that's a great way to monetize it. You could say, okay, well if I get one person who wants to coach with me or consult with me based off of this podcast, cool. (00:46:28): Then that is paying for the time I'm spending doing it. And then the other thing is with brands we talked about, I mean, it's the same thing really. It's like I buy from brands that I like and that I think are doing cool things. And the way I dictate that is like, are you telling good stories out in the ether of the internet? That's what I want to hear about. I don't want to hear about someone, another person, summiting K two. I'm like, it's cool, but I'd rather hear about these real stories and authentic connections that are happening in the outdoors. And I think that I'm not alone in that. And in fact, I think most of us want to hear that versus this elite athleticism that was shoved down our throats for years and years and years. So I think the payoff is for that aspect is just brand recognition, brand trust, super important especially right now and will continue to be and more important as we move forward. The payoff there is exponential as well. I think you're right. I think it's not just about how can I make the actual show pay off, it's about how can I serve a community and then eventually, because I've served at the community, maybe someone will want to work with me, whether that be for a brand or an individual.", "token_estimate": 608, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:45:14", "end_timestamp": "00:45:37", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "3689a058-da71-4986-9ae7-969323a7e5d1", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 23, "content": "Cole Heilborn (00:47:52): Yeah, well said. From the growth perspective of a podcast, I have no idea what are benchmarks for an audience size? If I'm getting five downloads an episode, is that good? If I'm getting 10,000, is that low? How does one begin to quantify that and how do you continue to grow that if that is a goal of yours?\n\nEmily Holland (00:48:18): Yeah, so let me try to answer the first one. The first one of what's the benchmark? The problem with benchmarking podcasts is that every podcast has a different reason for existing, especially in the outdoor space. So there's no transparency with who has what downloads outside of maybe brand conversations with sponsors. So unfortunately, there is no benchmark. You really don't know what the person next to you is doing. You have no idea unless you literally ask 'em. And that's a lot of why I started that Outdoor Podcasters Facebook group gave a shout out to that because there's so much of this mindset of, well, there's so many podcasts now we're all, we're not going to be able to get as much sponsorship because there's a finite amount of resources. Like, no, let's have an abundance mindset here. Everyone can get a piece of the pie that they need to get. (00:49:10): And it's not even a pie. It's like a whole ocean. Okay, bad metaphors, but you know what I'm talking about. So I think benchmarking is really hard, and I would also push back a little bit because yes, of course eventually when you get up to the 10,000 listener range, I would say that's pretty damn good for an outdoor podcast to get to that. I haven't heard of anything that's that much lower than that, that's incredibly successful. But again, what are your success metrics? Do you care about being in this upper echelon group where you're getting iHeartRadio awards and stuff like that? If you do, then that's awesome and keep going for that. But you need to come back to your Y and you need to come back to your success metrics. Are you hitting those, the intangibles like we talked about? Cool. Then you're successful and you don't need to benchmark yourself. So I think it's a little bit, that's kind of a cop out answer, but honestly, we don't have transparency to what the benchmark said. It's not like Instagram where you can be like, that person has 10,000 followers and I have two. So that's the first piece of it. And then the second piece of it is how you promote and grow. (00:50:28): A lot of what worked on the STO cast is not what works on the Nature Untold podcast. So the Stoke cast purposefully, we were reaching out to people who we admired that had big names. And so a lot of our growth came from those people sharing our podcast. And that is a big way that a lot of folks grow. I know a ton of podcasts that that's the basis of how they grow their own podcast is they just have really good guests on, and then it continues to spiral and spiral and spiral, and they'll reach different audiences because different folks follow different people.", "token_estimate": 751, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:47:52", "end_timestamp": "00:48:18", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "31210b77-e7a4-43ca-a9b5-f1e93e61145d", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 24, "content": "Cole Heilborn (00:51:00): I'm thinking of The Rich Role Podcast is a great example of that.\n\nEmily Holland (00:51:04): Yes, absolutely. And Rich Roll\n\nCole Heilborn (00:51:06): Does a fantastic job.\n\nEmily Holland (00:51:09): He is one of the best interviewers out there. I mean, his way of interviewing, even for people who I can tell he's bored by, I'm like, how is he still so interested in this person? It's amazing. Amazing. Yes, he's great. And then the other piece of it is that I usually recommend is you should go on other people's shows we're doing right now. I love going on other people's shows. I love doing swap interviews if can. It makes sense for the nature untold, of course. And the more people that listen to you on that person's audience will maybe be interested and they'll come to your podcast and they'll try to engage with you there. I mean, you can also do Facebook ads or Instagram ads. A lot of people come in through that.\n\nCole Heilborn (00:51:56): Is that actually a legitimate way to get podcast guests, or not guests? Sorry, listeners.\n\nEmily Holland (00:52:02): Yeah. And especially if I found, this is the thing that I've found is that if I do that and people start following along on Instagram or Facebook is I will message them immediately and I'll say, Hey, great to hear from you. Glad you're here in the community. How'd you find us? And I'll try to understand, okay, they came through an Instagram, okay, okay, what interests you about this? And I tried to have a conversation with them because I want to get to know them and then I link one of our episodes to them, say, start with this one and then we can talk something like that. Of course, that's time consuming, but I'd rather have an engaged 600 followers than an engaged 6,000 unengaged, 6,000 followers. So I think that's totally valid, and a lot of people came in that way through for the Stoke Cast as well. My co-host Jonathan, spent a lot of time and money on those ads and they actually worked very well. So I think that's a valid part of it too, is you advertise on your own. You can do $1 a day for a week and get a couple more actual engaged listeners from that.", "token_estimate": 543, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:51:00", "end_timestamp": "00:52:02", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "fc450124-f367-4d5a-87dd-59b165d708b1", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 25, "content": "Cole Heilborn (00:53:14): And Apple Reviews, are those important? I feel like every podcaster is plugging, give me a review, but what do they actually do?\n\nEmily Holland (00:53:21): Yeah, Apple's algorithm is absolute BS I'll say. So it really matters upfront. So you really need to push people to do it upfront when you are doing your first couple episodes. I reached out to all my friends, I was like, can you listen to this episode? And then if you like it, I don't make them do it. If you like it, can you leave me a review on Apple? Sure. It helps with the algorithm because the more reviews that you are showing, it shows that you're a consistent podcaster and it shows that people are engaged with your content, and so it's going to pop you up in searches more than if you didn't have any reviews there. It's like businesses right on Google, it's like if you see one without any reviews, you're like, well, I'm not going there. That is not happening. So it's the same kind of thinking. It's like the more reviews you have means the more engage your audience is means the more consistent of a podcaster you are means they're going to recommend you and they're recommending Engine now they do a shit job of recommending. So Apple is just like finicky in itself. Do not rely on that for your growth overall. But yes, you do need to kind of play the game of getting reviews and getting five star reviews hopefully on your podcast.\n\nCole Heilborn (00:54:34): Does it make a difference if you're on Apple versus Spotify or Google or the other a hundred sites that are out there?", "token_estimate": 395, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:53:14", "end_timestamp": "00:54:34", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "e406db9e-8644-4856-a62b-c82882bf77ce", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 26, "content": "Emily Holland (00:54:42): Stitcher, I don't understand where Stitcher is, but I know I'm on there somewhere. No, so absolutely you should use a distribution platform that gets you to all the different platforms. So you should be able to get onto Apple, get onto Spotify. Those are the main two big ones that you want to be on. Obviously there's different stuff for Google Play has some stuff in there, but most of the distribution platforms will push to all of those anyways, so you don't have to worry about that. But what I will say is when you're starting off is sometimes it takes a couple days for Apple or Spotify to recognize and confirm that you're a real podcast. And so that's why everyone starts with a trailer. They start with an intro to the show or they have a trailer so that once you're ready for your first actual episode, you're all set up and it'll just go directly to those platforms. So that's another thing to just think about that a lot of people don't necessarily know when they're starting out.\n\nCole Heilborn (00:55:45): And do you have any recommendations for distribution platforms because a number of those as well?", "token_estimate": 286, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:54:42", "end_timestamp": "00:55:45", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "971e5225-897a-4d62-ad3c-c420882e1881", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 27, "content": "Emily Holland (00:55:52): Yeah, I've only used Anchor, and I think it's super easy to use. So Anchor allows, you can edit, you can record in the actual platform itself, and you can also have people go to that and Tip you. You can have them directly give you money if you want. You can do your ads in there, you can see all of your analytics from there. So I think it's a pretty good platform overall. And what I do is I just edit separately. I edit an Adobe audition and then I plop the episode in there and you can schedule them out for weeks and weeks. So I've always used Anchor. That's my only experience, and that pushes to all the platforms that we just talked about. So that's the one that I would recommend. But it really doesn't matter what you use if you want to use, I know Buzzsprout is another one, Libsyn is another one. I think those are the main other two that are pretty longstanding. So choose what you like. I mean Anchor is free and it gives you direct analytics to demographics that you would need for brand sponsorship deck anyways. And I don't know if Buzz, Brad and Limon have the same analytics capabilities,\n\nCole Heilborn (00:57:03): Man, there's a lot here.\n\nEmily Holland (00:57:06): Yeah, I know. I'm getting fired up. Just thinking about it\n\nCole Heilborn (00:57:12): From the brand side though, there are brands that are creating podcasts. There's obviously the whole brand sponsoring solo creators. Is there any difference between those two?", "token_estimate": 369, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:55:52", "end_timestamp": "00:57:12", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "70b163f1-4535-4b0f-bebb-32bcc02e29f7", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 28, "content": "Emily Holland (00:57:24): Yes. So brand sponsoring solo creators. Well, again, it really depends on the agreement that they have, but generally that is they're giving them money to create the podcast. When a brand is creating a podcast, generally they'll have someone in-house who is tasked with production, editing, hosting, and they'll have a team in-house running that it's part of the content mill of other, any brand or should be rather. And so again, it really depends on their agreement that they have with the creator. For example, I think that for re i's Podcast Wild Idea is Worth Living. I believe that Shelby started that first, the host and then pitched them and then they took it on and have a whole team around it outside of just her that works with her. But for other folks like myself, I have a brand sponsor and they give me financial support and I produce the podcast myself and do everything else myself. They don't dictate anything to me. So I hate to say it depends as an answer, but that kind of is the answer.\n\nCole Heilborn (00:58:41): Podcasting, at least as I understand it, its origins were again kind of confusing, kind of under the radar, like people making stuff in their closets or their basements. But now that brands have started to see the value in the podcast, like you've said, they've started going out and producing their own. What does that mean for the solo creator? Does that take away from their audience, does that help them somehow?", "token_estimate": 370, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:57:24", "end_timestamp": "00:58:41", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "fefa9c0a-9ab2-4756-81c7-758430437db3", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 29, "content": "Emily Holland (00:59:11): Yeah. I never want us to think of anything as taking away, because there's people out there that'll listen to your podcast regardless. So there is a community for literally everything. There's, there's a podcast, there's like 70 podcasts about knitting. So I mean, the world is your oyster. So I just want to first say that. But the other thing is that brands starting to get savvy to podcasting is awesome because they could want to partner with someone who's already created a great show and they just want to support you financially and have their name attached to it. So if the brand goals are aligned to your mission, great, that's a great partnership. Then they don't have to go out and create their own podcast and they also can still get brand recognition for a podcast that's already created and already has great community around it. So I think that's awesome. (01:00:04): I think what's less likely to happen is that tons of brands will all create, and I'm talking about outdoor industry specific, will all create their own podcast in which they all have in-house teams for. I think that that seems like a big financial lift for them right now, especially when they probably still feel like podcasts are like we talked about the Wild West. So it's really hard to showcase return on a podcast unless you are using a discount code or affiliate code code. And so again, that might be a place in which they're like, Hmm, we don't want to necessarily create our own, but here's this cool show that's already created and they have this great community around it. Let's just sponsor that show and be like the title sponsor for them. And then you can craft your own deal as the individual creator.\n\nCole Heilborn (01:00:54): You mentioned the aspect of community that, I mean, there are some real passionate communities out there around podcasts. How does that get created?", "token_estimate": 476, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "00:59:11", "end_timestamp": "01:00:54", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "442fbd34-b875-46d9-aa7e-01d186683b97", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 30, "content": "Emily Holland (01:01:06): Yeah, I think this, again, everything goes back to your why. It goes back to the takeaways. It goes back to who you're trying to serve as your community. And I really like to use the word serve. I took that from a woman named Kathy Heller. Instead of selling something, you're serving a community. So I think those get created because the hosts are excited about the way in which they're telling stories and the people that they have coming on, and it starts to foster a following. No matter what you do, if you're consistently putting stuff out, you're going to start to foster a following. And with that following, if you're trying to create a community, you need to nurture it all the time. So that means, I was talking about before sending messages to people who are starting to follow you and saying like, Hey, how'd you find me? (01:01:56): I would love to hear about your story. Even offering one-on-one connections with them, things like that. Having, I really like having a private Facebook group that I manage and I add prompts to, and that people can connect with other folks who are like-minded or who are struggling with similar things. So I think that's a really cool way of connecting your community. And then a lot of Patreon, people who run Patreons have happy hours that they'll do with their Patreon supporters, and then they can all come together and get to know each other and talk about this one episode and like, oh, this was the biggest takeaway for me, or whatever. So I think there's all these different ways that you can really foster community as the creator of a podcast. And I think without fostering community, it can feel really hollow. And also you can feel really alone as the creator. So to know that there's people out there who are not only listening, but then they're sharing their takeaways with you or sharing their own stories with you and sharing with each other, that is really enriching, invaluable to them and also to you to keep that why at the front of your mind.", "token_estimate": 509, "speakers": ["Emily Holland"], "start_timestamp": "01:01:06", "end_timestamp": "01:01:06", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "f485821d-e599-4f8c-b6a1-e40059b1e982", "episode_id": "74c9bc87-9cef-49b5-a8b0-51ba882e9c99", "cms_item_id": "68225dfc7bb476527f8c4870", "chunk_index": 31, "content": "Cole Heilborn (01:03:11): Yeah. Well said. We're running out of time for today, but is there anything that we didn't cover that you feel like we should leave our audience with?\n\nEmily Holland (01:03:21): I don't think so. I mean, I feel like I could ramble on about things to consider when you're thinking about podcasting forever, but I think the thing to walk away with is that is possible. It is a lot of fun. At the end of the day, you're creating this really cool thing that no one in history of time besides us right now are understanding how much content is out there and how many cool conversations we get to be a part of. So it's really fun. It can be daunting, but it doesn't have to be. And I think more people just telling your stories and getting out there is super important. So I would just say if anyone has any questions, like my dms are open so they can reach out to me and I'd be happy to chat with them.\n\nCole Heilborn (01:04:06): And where can folks follow along with you? Where can they find your consulting business?\n\nEmily Holland (01:04:12): Yeah, that's Emily holland.co. And my Instagram is still a nickname that I gave myself, which is E Halls, H-O-L-L-Z. It's embarrassing, but I'm just going to continue going with it. I feel like with the Z, it makes me kind of younger than a millennial that I am. So those are the two best places I would say, to reach out. And also if you're a sober person or struggling with anything along those lines, always feel free. The dms are open for Nature Untold podcast as well. Yeah.\n\nCole Heilborn (01:04:48): Wonderful. Thank you Emily.\n\nEmily Holland (01:04:50): Yeah, thanks so much for having me on, Cole.\n\nCole Heilborn (01:04:52): Yeah, this was a lot of fun. Might as podcasts change in the next year or so, we might need to do a take two of this and revisit all of the changes.\n\nEmily Holland (01:05:01): Yeah, absolutely. I would love to that you can tell probably that I could talk for seven more hours. So yeah, let's\n\nCole Heilborn (01:05:06): Do it. Let's just roll into the next hour. We're good. Alright, well have a good rest of your day and take care.\n\nEmily Holland (01:05:13): Alright, talk to you soon.\n\nCole Heilborn (01:05:16): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 606, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "01:03:11", "end_timestamp": "01:05:16", "podcast_index": 73, "episode_name": "EP 73: Emily Holland | Starting a Podcast | Nature Untold Podcast", "slug": "ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "web_url": "https://www.portsidepro.com/podcast-feed/ep-73-emily-holland-starting-a-podcast-nature-untold-podcast", "guest_name": "Emily Holland", "guest_title": "Host, Nature Untold Podcast", "categories": [], "short_description": "In this episode, Emily Holland, the host from the Nature Untold Podcast breaks down all of the details to start a podcast. We discuss defining your \"why\", format, software, sponsorships, Patreon, and marketing.", "podcast_length": "44:95"}, {"id": "12dda704-7167-4892-ae25-fb43ffc9bd08", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 0, "content": "Colton Jacobs (00:06): As a creative, having a website is incredibly important. Having a website that depicts the type of work you want to be hired for, not just, I mean, if you want to be hired for a landscape photographer, then post landscape photography, but that's not how you make money as a landscape photographer traditionally, unless you're putting it on stock, you're selling prints. So don't just put a website full of just photos of landscape. Put a website full of prints that you can sell.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing Podcast. My name is cool and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Hibour, and today I'm sitting down with Colton Jacobs. He's a commercial, outdoor, and advertising photographer slash director of photography. Colton, how are you?\n\nColton Jacobs (01:15): I'm doing well. Excited to be on.\n\nCole Heilborn (01:18): Yeah, thanks for joining us today. You're just down in Seattle, correct?\n\nColton Jacobs (01:22): I am. I'm here right now in my office.\n\nCole Heilborn (01:27): I've got to say, we were just talking about it earlier, but your office is pretty sweet. It's like a mix between a photo studio slash gear room. It seems to fit your personality very well from what I understand about you.", "token_estimate": 446, "speakers": ["Colton Jacobs", "Cole Heilborn"], "start_timestamp": "00:06", "end_timestamp": "01:27", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "33e79575-cf2c-4498-8ee7-41484136314e", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 1, "content": "Colton Jacobs (01:39): Yeah, it's quite the clutter. Again, it's a lot of conversations on Zoom meetings and first time Zoom affiliates. They're always asking questions like, oh, what's that and what's that? And I try and clean it up before each meeting. Sometimes there's underwear long Johns, and depending on the season, there's skins from the splitboard hanging and camera gear explosion and mountain bike socks, and it usually has a pretty poor odor. So it looks like the really, really trashed used section of the REI garage sale.\n\nCole Heilborn (02:21): Hey man, say what you want. I think the REI garage sale, that's one of the few times that I spend a lot of time and money at REI. It is pretty incredible.\n\nColton Jacobs (02:33): I would agree. I've spent some serious coin at the garage sale,\n\nCole Heilborn (02:38): So I'm super excited to jump into our topic for today. But first I'd love if you could give us a quick introduction and you mentioned that you're into splitboarding and mountain biking. What other hobbies can we typically find you doing?", "token_estimate": 267, "speakers": ["Colton Jacobs", "Cole Heilborn"], "start_timestamp": "01:39", "end_timestamp": "02:38", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "4e747011-82b2-466e-932d-c11e02ba13bb", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 2, "content": "Colton Jacobs (02:53): That's a good question. It changes a lot, I mean, by the season, but each season to year can be different. So typically I guess my staple sports would be skiing, or excuse me, snowboarding. I ski uphill on a splitboard a lot back country skiing, mountain biking, fly fishing. I've done a lot of mountaineering and climbing and backpacking here in Washington since I've moved here, which I mean, I've been here almost 10 years now with a few hiatus of moving to Bend Oregon, but a lot of mountaineering for the majority of those 10 years. But I'm starting to spend a little less time mountaineering and backpacking and more. I've been focused a lot of mountain biking the last couple of years. I still will go climb a lot, but you start to, I've started to be very selective of my missions because I've done a lot of them, but I also starting to get busier, so taking off just for a week to go somewhere that I've already been is less enticing. So I've been doing a lot more mountain biking in the summertime, but usually there's a steady amount of fly fishing and snowboarding all winter. Yeah, that's kind of what got me started in photography was the snowboard industry was my foot in the door.\n\nCole Heilborn (04:33): Very cool. Yeah, that's right. You got started originally kind of with your photo journey working at K two, right?", "token_estimate": 340, "speakers": ["Colton Jacobs", "Cole Heilborn"], "start_timestamp": "02:53", "end_timestamp": "04:33", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "0f9f6ca8-4e0b-4a62-83b2-fc302fc7030e", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 3, "content": "Colton Jacobs (04:39): Yep. I started at K two. I was not a photographer. I was 18. Yeah, fresh off a broken neck, starting at K two, that's a whole nother story, and I worked at K two for several years, just I was getting into backcountry skiing and I was always out adventuring and I was shooting photos and started taking it more seriously and just a side hobby. And then I started shooting photos and of splitboarding and skiing and snowboarding, and then the marketing teams, they were all my friends at this point, started using some of the photos, asking if I was the trade for boards and stuff like that. I was just a hobbyist. Yeah. And then eventually I got myself fired from K two for pursuing photography related activities, which turns out to be the best thing that could ever happen to my photography career, was getting fired from K two. Now I work with K two a lot just as a on Crown Tractor freelance right now, and they've just been like, yeah, starting at K two, I'm still really good friends with them all and they've been such a great client and good friends, and that's where I got started\n\nCole Heilborn (06:07): Right on. And it should be noted that I think you mentioned it, but everyone at K two who you used to work with, you're still really good friends with, and the whole getting fired thing was like a, I don't know. It is its own story.\n\nColton Jacobs (06:20): Yeah, it's its own story that I don't know how much detail I should go into. It's a very funny story, and usually everyone I'm still friends with, I'm friends with my boss who fired me, and I think it was, I'll call it less. I think technically we'll just be technical. It was a firing, but it was a mutual agreement that part ways, but done by a very poor decision making 20-year-old or 21, I don't know how old I was, but I was just being irrational and just really dove right into what I thought I knew I could do, and I apparently figured out a way to do it because here I'm six or seven years later and found a way to make it as a freelance photographer.\n\nCole Heilborn (07:09): Yeah, that's awesome, man. Congratulations. And your work is phenomenal. Who are some of the clients that you've worked with?", "token_estimate": 551, "speakers": ["Colton Jacobs", "Cole Heilborn"], "start_timestamp": "04:39", "end_timestamp": "07:09", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "a8ffd331-cb38-45fb-a31b-cce4071ad915", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 4, "content": "Colton Jacobs (07:16): K two has been steady for years. I've done this last year, I've been part of a three or four month project for Patagonia on a snowboard bike related project, which is not, I mean the world's seen a bit of it, but it's not out yet or released yet. We're still figuring out how we're fully going to tell that story. Oh man. I've done a lot of outdoor, I mean, a lot of the brands that you see in REI, let's see here. Let me do some brainstorm thinking. I think I used to have, I mean, K two has a bunch of brands, no, eight or nine, there used to be eight or nine. There's a lot of brands in-house at K two, I'm on contract with this brand called Yuko Gear. I do a lot of their product photography in the studio and then their seasonal shoots every year. And this question gets asked and I space out on, it's all over the board honestly.\n\nCole Heilborn (08:34): Yeah, I think I remember telling me you do some work with Filson, you've done some work with Ride Snowboards, shop some stuff for Cyclecross Nationals, so you definitely, you've got a wide spectrum. Yeah, man. I mean those are some pretty phenomenal clients and I got to assume, and I know speaking personally and just my conversations with you that figuring out how to get started as a photographer, finding clients and building up the repertoire and kind of the reputation to attract more clients and bigger clients and bigger jobs is I feel like it's the part of the business that no one really talks about. We always talk about the photography side or the video side or the portfolio side, but we never really talk about, well, how do you actually get the clients? How do you find the jobs to actually not just pay rent, but also hopefully be able to create a good living for yourself? So I'm excited to dig into this and hear your thoughts and hopefully we can break down some ways that people can just consider as they're trying to figure out how to get into the photo game or just take their photo game to the next level.", "token_estimate": 503, "speakers": ["Colton Jacobs", "Cole Heilborn"], "start_timestamp": "07:16", "end_timestamp": "08:34", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "0baefff7-7658-4b64-bbe5-61d136cb58f9", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 5, "content": "Colton Jacobs (09:45): Yeah, I'm happy to talk about this. I mean, I want to be full disclosure. This is obviously what's worked for me and how I've been trial and error, figuring out my way to make it as a freelance photographer. Certainly not the only way. I think there's the saying there's a dozen ways to skin cat or a million ways to skin a cat, something like that, something like that. But yeah, I mean, getting the client is half the job and then keeping the client, and I think as a photographer or a creative or whatever your profession, that client retention is an often overlooked part of the business because I mean, you've done all the hard work to get noticed and they've taken a risk and hired you, and if you're not careful, you can book yourself so busy and spread yourself so thin that maybe you're going through the post-processing process and you're just really chomping out the bit to get to the next job, and you don't pay enough attention to just making sure that client's happy or following it through and your work can suffer or whatever, and you can just be like, maybe you already got paid too. (11:21): Maybe you got paid, and you're just like, I just want to get this done and get it out of my hair. And that's not what the client wants. The client wants you to follow through a hundred percent. So I think that making sure you don't do that because keeping that client happy and making sure that they're happy after you deliver, and that's a big part of the business because then you've got 'em for the next job and until you screw that up, I mean chances are if they're happy, they're going to hire you again.", "token_estimate": 411, "speakers": ["Colton Jacobs"], "start_timestamp": "09:45", "end_timestamp": "09:45", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "64c2a980-8f15-4892-9c9f-6fcca9c0a539", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 6, "content": "Cole Heilborn (11:51): Yeah, that's a great point. We often spend so many times thinking about how do I get the next client or the next biggest client, but maybe it's a little of that mind shift, that perspective shift in recognizing, well, maybe I just need to focus on the ones that I do. Have you brought up something interesting though, this idea of trial and error. I do feel like being a creative, being a photographer at some point, it's just kind of attrition. You just have to survive as long as you can until you reach a place where you're no longer surviving. I'm curious if you could just give our audience a laundry list of all the different ways that you have tried to get work, and we don't need to go into what has worked and what hasn't worked, but I think just to give a good idea of the depth of things that successful creatives have had to do to gain their footing.", "token_estimate": 222, "speakers": ["Cole Heilborn"], "start_timestamp": "11:51", "end_timestamp": "11:51", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "2c29bffb-e37f-469c-b139-dcf2bee211ba", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 7, "content": "Colton Jacobs (12:39): Let me start thinking, I'll start as basic as, I mean creating a website. Maybe I'll go here and filter some that I know have worked and some that I'm not sure. Are jury's still out? I think as a creative, having a website is incredibly important. Having a website that depicts the type of work you want to be hired for, not just, I mean, if you want to be hired for a landscape photographer, then post landscape photography, but that's not how you make money as a landscape photographer traditionally, unless you're putting it on stock, you're selling prints. So don't just put a website full of just photos of landscape, put a website full of prints that you can sell if you want to be hired for me, outdoor sports photography, then post that sort of and make sure it's clean, make sure it's good, make sure it is on par with a lot of what the client, your dream client would hire you for. (13:45): So website, I think social media is undeniably important here. As much as some of us might hate it, I think some people are really good at it and the rest of us just envy them, but for one, I'm not, I'd say I'm decent on social media, but I have not built a massive following. And so I think a lot of people might put too much importance on a social media. I think it's very important. It's a portfolio that people go to and profile you immediately faster than a website. That's usually probably the chain of events that go to your Instagram and then they look at your website and then maybe somewhere else. So share the work on your Instagram or your social media, whether it's, I don't know, TikTok, there's probably a really creative way to do that. I've dabbled in that, but jury's still odd on if I'm ever going to actually pursue TikTok, I'm going to go ahead and say no right now, but Instagram and share the stuff that you want to get hired for one, I'll talk about in my experience, I spent years I wanting to be, I don't know if I wanted to be an influencer, but I wanted to have hundreds of thousands of followers. (14:58): I thought like, oh, that's a great way to be a photographer is get a ton of people to notice your work and then they'll hire you. So I had this mindset that maybe I'll be a commercial photographer with tons of followers, but that's not necessarily the average person out there. Most people or influencers share beautiful work in the photos from landscapes and they travel all over the world all the time. If you're going to a commercial advertising photographer or you're just not in those situations. So it's hard to build a massive, so I spent too much time trying to do that, and once you realize it, this is another portfolio, share the work you want to get hired for, then I think that it will be beneficial. You may not have thousands of followers, but you might have the follower that matters are your creative directors, your photo editors, your marketing managers, those are the people you want to attract ultimately because having 30,000 14-year-old to 18-year-old kids phone you is cool in the comment section, but not so much going to pay your bill. (16:08): And that leads me to LinkedIn. LinkedIn's an easy way to ensure that you get the eyes that you want on your pieces. So being active on LinkedIn I think is often again overlooked, especially by the younger outdoor sports or the outdoor photographer world, which I'm in. Everyone wants to spend time outdoors and LinkedIn is not very exciting. So being active on that and sharing the work that you want to get hired for, again, not just a bunch of stuff and share, be very professional on LinkedIn and then reach out to the people you want to get hired by and be smart about it. And you don't have to send each person a detailed reason why they should hire you. Just try and connect with them that way when you share work that they might be interested in then, or at least they see your work that you're sharing and the next time you email 'em, they'll have a good reference of your name because they've been seeing your stuff on their LinkedIn and that. (17:15): Then maybe they never do email you out of nowhere, but if they've been seeing your stuff and they like it enough to like it, then when you email them and you have some good idea to reach out to them, maybe they've seen enough to hire you at that point and they're familiar with you. So I think LinkedIn a good way. And what have I covered so far? Instagram, LinkedIn website. I think for me working, this is not so much getting new clients, but this is, I mean, networking, it's who and that really is in this industry I guess everyone says in this industry it's all industries, but I think particularly in this industry, I mean everyone wants to be hire their homies. Why wouldn't you? Right? (18:13): I mean working at K two and these other brands, being friends with someone and genuinely taking interest in them and building your network, staying communic, you don't have to be best friends with them, but being in good relationship with them and staying in contact and building that network. And then when that person, maybe they leave that company that you worked with once, but you stayed good friends with them and you made sure you did good work. Next time they go to another company, they're not going to forget you and may be a completely different industry, which I've had. I've had a friend go to a random company that's completely out of my general realm of work, but then they like you, that just goes to show the power of just being a good friend or being someone who's easy to work with because your portfolio may not have anything to do with this. (19:10): Your friend had gone to a new company, but they're your friend. They like your work and they think you're easy to work with, and a lot of times that's what matters most. I think I've said it before when we were chatting, unless you're an elite photographer, the best in your field, chances are you're not getting headhunted mean or you've got hundreds of thousands of followers or whatever. You've got a huge audience. You're not necessarily getting headhunted. So what are you going to do? What are you going to do to set yourself up as being a good photographer? Being someone worth hiring? Because I promise you, I'm not the best photographer in Seattle even, but I think I'm probably easy to work with and I've done my best to try and understand what the clients want and be on the same page with them and make sure that they're happy. And I think they recognize that. I think they don't necessarily need the very best photographer. Everyone would want it, but they're probably expensive too. But also you just got to hire the people that you had a good experience with and I think that's a lot of times keeping the client, as long as they're happy, man, they're going to hire you again usually, unless you completely blew it.", "token_estimate": 1725, "speakers": ["Colton Jacobs"], "start_timestamp": "12:39", "end_timestamp": "12:39", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "11d1a400-269e-4beb-ae36-6b81c7a748aa", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 8, "content": "Cole Heilborn (20:42): I mean, case in point, I guess what you're saying is there's no one way to do it, which I think we're all aware of. Out of all the things you've mentioned, I think there's things that yeah, people could start a website, they could do the whole Instagram thing. We know networking is important, but behind all of those, is there a bigger idea or a deeper message that needs to be considered when you're kind of doing all these more tactical, different processes,\n\nColton Jacobs (21:12): A bigger message\n\nCole Heilborn (21:14): Or maybe not bigger, just like a layer behind it all?\n\nColton Jacobs (21:20): I mean, being creative, there's no one way to do it. I think being, having a lot of different avenues out there, you can get hired being everywhere if you can on all platforms, on all websites out there. Cold calling, I don't know if people answer the phone anymore, but emailing, reaching out, get creative with emails, the bigger message that there's no one way to do it and the more feelers, roots you've got out looking for clients, the better you're going to be. But I would say don't do anything half-assed. Make sure your message, make sure it's not just a very loose attempt. Be professional. And because brands, especially the big brands that all of us want to work with, want professionals and they can usually sniff. I've been sniffed out as being not ready for a client. I think I've had a few where I've underbid and reached, I got their attention and then they wanted to talk and then they realized they're like, you need more experience for this big of a job, and that's okay. That'll come. That's the growing process as elite top commercial photographers that have a massive team and they're usually got a ton of experience and they got there by plenty of denials. They've got plenty of failures too. So don't be afraid to fail for sure, because that's all part of the process.", "token_estimate": 481, "speakers": ["Cole Heilborn", "Colton Jacobs"], "start_timestamp": "20:42", "end_timestamp": "21:20", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "125f2c3b-1b21-45a7-a6c6-23b3f88e90b6", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 9, "content": "Cole Heilborn (23:17): One thing that I've heard is people describe it as the snowball effect. You get one client and that helps get you to the next one and then the next one. And I have found that metaphor really frustrating, but also at the same time, it is true, at least from the experience that I've observed, this idea that everything builds on top of each other. I don't like that because it doesn't actually give you any advice other than just keep going. And maybe that is the advice", "token_estimate": 123, "speakers": ["Cole Heilborn"], "start_timestamp": "23:17", "end_timestamp": "23:17", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "1e9c8571-798e-4ae3-89c3-9c05743b4057", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 10, "content": "Colton Jacobs (23:48): I had this thought as you were saying that I would argue that it's not a snowball. It is a snowball to a point, but then sometimes for me, yes, definitely I felt the snowball effect. It took years of several years before I feel like I finally got a steady momentum going. But then even still when I get really busy and I start getting some steam built up and I'm like, I got that snowball effect. If you don't pay attention to the business side of your business, then you may book yourself up. You're like, you're networking, you're emailing, you're trying to get work here and there, and you're just hustling. Well, then when you start getting work and you start booking 'em up, then what do you start doing? You starting too busy to start looking for more work when that job's done. So I have found that in my past when I get really busy, I'll go through spells of four or five months really, really busy and then a couple months of nothing. (24:55): And that's because not nothing but a couple months where it's not as busy. I'm like, what? I wonder why this was, and I've seen it over and over and I've come to realize it's like, okay, you got to spend time to continually be thinking of new projects or new concepts. If you do a lot of pitching, continue pitching projects because as soon as you get wrapped up on a few projects that are really busy keeping you busy, then you neglect the necessary business side of networking and emailing and trying to secure work down the road. So that snowball effect, while it is true in a big grand scheme of things as a career, your career starts rolling down to a job by job snowball effect. It can be patchy as you get busy neglect work, neglect the networking and hunting for jobs or reaching out to old clients.\n\nCole Heilborn (25:52): It's kind of that feast or famine scenario.\n\nColton Jacobs (25:55): Yeah, and sometimes we induce our own famine by feasting too hard. You hear about businesses growing too quick. It's kind of like they grow so fast that they implode, which I'm not quite sure I understand entirely how that works, but it sounds like a good thing to grow fast, but it's kind of the same thing I think.", "token_estimate": 548, "speakers": ["Colton Jacobs", "Cole Heilborn"], "start_timestamp": "23:48", "end_timestamp": "25:55", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "30918346-45e5-4dea-bd9f-4930ad61be22", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 11, "content": "Cole Heilborn (26:13): So how do you manage that cycle? Do you just have to make time for yourself to always be putting steady pressure on the marketing and sales side?\n\nColton Jacobs (26:23): I've failed enough at not putting enough attention into it, but yeah, I've after repetitive patterns where I've seen it, that's what I do. Yeah, I have lists of a to-do list that's entirely of who to reach out to and who to pitch and continue to do that, and I try and do a couple a week or whatever set a goal. I mean success rate as I've found. You can pitch tons like this. I don't know. I don't have a proper ratio, but it's not a lot of, I mean, I pitch a lot, I talk a lot to a lot of friends and clients, but very few of 'em actually follow through onto the big project. So send out as much as you can, do some every week of emailing and following up with projects. And I mean a lot of times people get really busy with jobs in their emails. Just get backed up if you read the email and you can respond to it right then and keep the conversation going. Don't let it get buried way down in your email and then your next thing you know you're reaching out like, Hey, do you still want to do this? Three weeks later? Like, Hey, sorry I've been busy. That client's already gone found another photographer.\n\nCole Heilborn (27:39): One thing that I've also realized and I'm curious to hear your perspective on is how much work do you actually need or how many contacts do you actually need? Because networking, this idea of constantly going out knocking on people's doors is one kind of intimidating and two, at least it can be extremely draining, but I think it makes it better when you realize that you actually don't need that many good connections. You really just need a few solid ones. Have you noticed that?", "token_estimate": 452, "speakers": ["Cole Heilborn", "Colton Jacobs"], "start_timestamp": "26:13", "end_timestamp": "27:39", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "e88e5f67-7522-45e2-adcb-7d105243f51b", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 12, "content": "Colton Jacobs (28:11): Absolutely. Absolutely. I mean, you said it is exhausting and hard and not easy to get new clients over and over and over. And the idea that you have to have a ton of clients to stay in business or to just make a good living is not true. You need a few, and depending on how big the client, I know plenty of people who shoot a lot for one or two brands, they're big brands, they got in with big brands, and that's everyone's goal. For one, I want to stay freelance. I don't necessarily want to be the photo guy nine to five or be work for one particular brand. I want to stay contract. But being on retainer or being on contract with a few brands that you really work well with and they're like, maybe they're your dream brand or dream client, or maybe they're not. (29:16): Maybe they're just great people and you work well with them and you've gotten to really identify their strategy, their aesthetic, and you're really like you and their team really work well together. That's the goal because you don't want to have to figure that out every time you get a new client over and over and over have to go through that process. So having a handful of really good clients that you work well with and retaining them, making sure they're happy with how you're doing after every job is way more important than having a bunch of variety. I mean, it's fun to have new clients for sure. New client comes, it's like it's exciting. I mean, and take care of that client too, but don't ignore the ones you already have because having just a handful of clients that come back to you and back to you and back to you is way more important than trying to find a new client every month.\n\nCole Heilborn (30:16): Have you heard of Blair Ends?\n\nColton Jacobs (30:18): I don't think so.", "token_estimate": 448, "speakers": ["Colton Jacobs", "Cole Heilborn"], "start_timestamp": "28:11", "end_timestamp": "30:18", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "34327989-aa3f-4dac-9b85-4a91a05c5947", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 13, "content": "Cole Heilborn (30:20): I'm pretty sure I got his last name right. I feel bad. I actually own a book that he wrote and it's sitting on my bookshelf, I'm looking at it right now, but he's a creative, like an agency consulting strategist. He wrote the book Win Without Pitching Manifesto or the Win Without Pitching Manifesto, and he kind of has this guiding principle that he tries to instill on agencies, and it's a little different I think in the contract photo world, but his whole thing is you should try to limit yourself to only have 10 clients at a time, and in doing so, it makes sure that you have enough capacity to serve those clients. It also makes sure that you can give them the attention that you want to be able to give them, and it forces you to charge enough to maintain your standard of living, but without having to compromise on those first two points. I always thought I heard that six months ago. I was like, wow, what if you did only have 10 clients a year? What would that actually look like?", "token_estimate": 254, "speakers": ["Cole Heilborn"], "start_timestamp": "30:20", "end_timestamp": "30:20", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "94c3db5f-2b60-4a0c-a178-83cc189d044e", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 14, "content": "Colton Jacobs (31:29): I agree, or whatever it is. I would just say, if your number one client is demanding a ton of your time and it's worth it, it's paying proper, then you don't need 20 clients or 10. You can have that client and a couple other ones to if you're making what you want to make eventually. I think it is important to be aware of industry standard of prices and rates and stuff. That way you're not undercutting anyone. So maybe that one client's demanding a ton of your time, you come to realize, well, maybe I'm selling myself short, I'm working too cheap. So I would say if you've got having 10 clients that you work hand in hand with really great and try and as you get more experienced and you become more efficient, just like any career, you get raises. So make sure your prices are still competitive and your cheapest client or the client that wants the least or tries to cheap you the most, you will lose clients because you outgrow them when you're first starting. (32:42): You work for cheap and they take advantage of the fact that you're cheap. And when you start gaining the experience and your day rate goes up and you deserve more, you have a lot of gear and there's a lot of costs and making, especially here in Seattle to live as a photographer in Seattle, it's expensive and so to say the least. So making sure your value and your rate clients will, that's hard because especially when you work for cheap and a client knows what they paid for you for one at one point in time, if they're really happy with you and you're able to bring them with you as you get more expensive, that would be incredible if you could do that. But not everyone can do that, understandably. So I think just continue to build 10 clients that will pay what you deserve and what you value yourself as. And don't worry about the rest. If you can just keep those guys happy, that's probably plenty.\n\nCole Heilborn (33:50): I'm curious, what's the biggest mistake you've made in trying to work with a client and what did you learn through this process or what did you learn about yourself through it all?", "token_estimate": 528, "speakers": ["Colton Jacobs", "Cole Heilborn"], "start_timestamp": "31:29", "end_timestamp": "33:50", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "2fa1c600-8a53-4516-9091-8a4fac55a504", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 15, "content": "Colton Jacobs (34:05): I don't know the biggest one, but I'll think of one that just came to my mind just now is early on as a photographer, I really worried about my style or my aesthetic having a super unique creative treatment to my images, my photos, and I would go crazy with edits after a in between from one photo shoot to the next, I would be build a whole new, reinvent my base presets and get all crazy. And I'm sure clients were like, whoa, what in the heck? And so I think that's probably a mistake that I made early of just being like, yeah, this client wants, I'm going to get all filmy with this, and there's going to be some crazy film preset. Generally speaking though, I think it's important to have that conversation with a client and some clients actually don't know what they want. So as zero photographer, that's sometimes your job to look at their brand aesthetic and try and patch in your work into that. (35:17): Hopefully the brand has a creative director or someone who's has, that's their job to have their pulse on the brand image and all of that. I've worked with brands that they know exactly the type of settings down to the clarity, the little tools that you use in Photoshop or in Lightroom being like, yeah, these tones and this edit is a little bit more like our style, which is incredible. When a brain can be like, Hey, we really like shooting these compositions and these edits and this treatment, like sweet, then that just makes it even easier for me to make you happy. I know how. So having that conversation with a brand with a client will never harm you. That's great. But sometimes they just don't have that resource, they just don't have the opportunity. So I'm not overdoing the edits. I think I over maybe not overdid it, I mean it was overdid, but overthought like a look. So many clients just want color natural. It's not necessarily about, you can do a lot of stuff in Photoshop and Lightroom, but it's more about your ability out in the field. It's not about your gear, it's how you use it. (36:41): So if you delivered a whole bunch of out of camera raw photos, or they probably would be stoked on it if they were good photos, if they're good compositions and you shot it well, then you could put no priest, no edit on it, and they would probably be jacked on it. I'm not saying that's a good idea, but they'd be more stoked on that than if you put some crazy filter on it because you were trying to find an aesthetic. So I think that's an often overdone mistake. I certainly made that mistake early on of getting too crazy with that. And then brands, they won't want to rehire you after that.", "token_estimate": 662, "speakers": ["Colton Jacobs"], "start_timestamp": "34:05", "end_timestamp": "34:05", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}, {"id": "46a5cc64-7710-4095-afb7-b9602897f924", "episode_id": "b8d76cb1-de4e-4e7d-b3a5-39a3ce5e1f3b", "cms_item_id": "68225dfc7bb476527f8c4872", "chunk_index": 16, "content": "Cole Heilborn (37:20): What do most aspiring photographers get wrong about finding work?\n\nColton Jacobs (37:24): What do they get wrong about finding work? They search it in the wrong places. I think a lot. I mean, today's era of social media, and so people will be DMing brands constantly trying to get work from DMing a brand. That probably works sometimes, but if you've got a massive portfolio and a great portfolio, that might work. But if you're new and aspiring, that's not going to work. Not success, not a sustainable success rate. You might find some, but brands get speaking on behalf of someone who has ran brands Instagrams before. You get spammed with people wanting to work all the time. And brands have a handful of photographers that they work with and that's the ones they want to work with. Just the same as a photographer has a few clients they work with. Brands only want ideally to have a few people they work with and not have to deal with that hassle, learning someone new all the time. (38:36): So just spraying dms and Instagram or trying to rely on social media is not going to work unless you've figured out something that the rest of us haven't done or haven't figured out. But I don't think that's a sustainable way to find work. I mean, as your portfolio gets better, you'll definitely start to get work from Instagram or you'll get eyes, people will find you and then they'll do the diligent of investigating if they're like a creative director or someone like that. But social media is definitely valuable for stuff like that. But relying on that when you don't have a portfolio or you're just starting is not the right way.\n\nCole Heilborn (39:13): What's the balance between your portfolio and your network? I mean, we've clearly, I think, identified that sometimes it's all about who, and not necessarily how good your skills are up to a point, but what is the point where your portfolio is kind of irrelevant? Is there a tipping point or a line in the sand where it's really again about the network?", "token_estimate": 509, "speakers": ["Cole Heilborn", "Colton Jacobs"], "start_timestamp": "37:20", "end_timestamp": "39:13", "podcast_index": 74, "episode_name": "EP 74: Colton Jacobs | Finding Work as a Photographer | Colton Jacobs Photography", "slug": "ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-74-colton-jacobs-finding-work-as-a-photographer-colton-jacobs-photography", "guest_name": "Colton Jacobs", "guest_title": "Photographer", "categories": [], "short_description": "In this episode, Colton Jacobs, a Seattle-based adventure photographer shares his thoughts on finding and keeping clients. Colton has shot with many brands such as Filson, K2, Hest, and many other reputable brands.", "podcast_length": "44:96"}]
